var enclosures = {
"type": "FeatureCollection",
"name": "enclosures",
"crs": { "type": "name", "properties": { "name": "urn:ogc:def:crs:OGC:1.3:CRS84" } },
"features": [
{ "type": "Feature", "properties": { "fid": 0, "name": "Papużki", "comments": "<b> Papużka nimfa </b> pomimo swoich małych rozmiarów jest spokrewniona z kakadu. W celu kamuflażu większość czasu spędzają na wyschniętych gałęziach. Pobierają wodę gromadzocą się w formie rosy na liściach oraz kwiatach. Dodatkowo dietę uzupełniają małymi owocami. Nimfy najczęściej czyszczą się wzajemnie. <br><br> <b> Papużka falista </b> swoją nazwę zawdzięcza ułożeniu piór wykończonych na czarno w kształcie fal. Podobnie jak większość papug zarówno samiec i samica potrafi naśladować odgłosy oraz nauczyć się pojedynczych wyrazów - z czasem też całe zdania. W naturze spotkać można przeważnie papużki w odcieniach zieleni, jednak dzięki hodowli uzyskano wielobarwne odmiany. Pierwsze papugi trafiły do Europy w XIX wieku.'", "category": "Dziecięce Zoo", "icon": "Ppg" }, "geometry": { "type": "Point", "coordinates": [ 16.994263537502423, 52.400222995571916 ] } },
{ "type": "Feature", "properties": { "fid": 1, "name": "Koza karłowata", "comments": "Jedna z najstarszych udomowionych zwierząt około 10 tys. lat temu na terenie Bliskiego Wschodu, Mongolii, Azji Południowo-Wschodniej oraz Indii. Rozwinięty wzrok pozwala na rozróżnianie takich kolorów jak żółty, pomarańczowy, fioletowy i zielony. Mają niezwykle rozwinięty zmysł węchu i smaku. Rozróżniają smak gorzki, słony, słodki i kwaśny. Mają dobry wzrok, a nowe pożywienie często najpierw obwąchowują. Jest zwierzęciem stadnym, w którym obowiązuje hierarchia. Uderzanie się rogami, oznacza walkę o status hierarchii w stadzie. <br> <img src='./Animal_photos/1.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Dziecięce Zoo", "icon": "DzKo" }, "geometry": { "type": "Point", "coordinates": [ 16.99419462892935, 52.400056035500263 ] } },
{ "type": "Feature", "properties": { "fid": 2, "name": "Alpaka", "comments": "Udomowiana przez Inków 4500 lat temu. Z wełny alpaki Inkowie wytwarzali tkaninę nazywaną także alpaką. Dobrze wspina się na skalne urwiska. Jest odporna na zmienne warunki klimatyczne. Należy do rodziny wielbłądowatych, zaś jej przodkiem jest wikunia. Podobnie jak jej kuzynki, potrafi opluć gdy poczuje się zaniepokojona. Alpaka to zwierzę stadne, musi żyć w towarzystwie innych alpak. <br> <img src='./Animal_photos/2.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Dziecięce Zoo", "icon": "DzAl" }, "geometry": { "type": "Point", "coordinates": [ 16.994167908079746, 52.39988547467842 ] } },
{ "type": "Feature", "properties": { "fid": 3, "name": "Osioł domowy", "comments": "Udomowiony wcześniej od konia czyli 4000 lat p.n.e. w rejonie Dolnego Nilu. Dzięki niskim wymaganiom pokarmowym wykorzystywany jest przede wszystkim jako zwierzę juczne, które dodatkowo dobrze znosi górskie tereny. W stanie dzikim występuje w Afryce, zaś za jego przodka uważa się osła somalijskiego. Przez blisko 6 tysięcy lat wyhodowano ponad 70 raz osłów. Osły żyją w stadach 10-15 osobników. Stadu przewodzi doświadczona oślica, zaś same osobniki mogą dożywać do 40 lat.  <br> <img src='./Animal_photos/3.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Dziecięce Zoo", "icon": "DzOd" }, "geometry": { "type": "Point", "coordinates": [ 16.994163797179805, 52.399702371885901 ] } },
{ "type": "Feature", "properties": { "fid": 4, "name": "Kuc szetlandzki", "comments": "Rasa koni zaliczanych do kuców, pochodząca z Wysp Szetlandzkich. Jest jednym z najmniejszych ras wśród kuców. Wysokość w kłębie osiąga maksymalne 110cm. Ich charakterystyczną cechą jest wytrzymałość, długowieczność, upartość i łagodność. Stąd dawniej wykorzystywane były do pracy w kopalniach. Gruba grzywa, długie włosy ogonowe, krótkie uszy oraz gęsta sierść, zabezpiecza przed złymi warunkami atmosferycznymi.  <br> <img src='./Animal_photos/4.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Dziecięce Zoo", "icon": "DzKs" }, "geometry": { "type": "Point", "coordinates": [ 16.994222377503938, 52.399458442670259 ] } },
{ "type": "Feature", "properties": { "fid": 5, "name": "Kura domowa ozdobna", "comments": "Brak opisu", "category": "Dziecięce Zoo", "icon": "DzKd" }, "geometry": { "type": "Point", "coordinates": [ 16.99459060362318, 52.399797086083503 ] } },
{ "type": "Feature", "properties": { "fid": 7, "name": "Leniuchowiec dwupalczasy (leniwiec)", "comments": "Przez rdzennych mieszkańców Ameryki Południowej zwany jest unau. Większość czasu spędza zwisając z drzew grzbietem w dół. Nie częściej niż raz w tygodniu schodzi na ziemię w celu wypróżnienia się. Futro złożone jest z dwuch warstw: krótkie wełniste oraz dłuższe skierowane ku grzbietowi. Kolor sierści - brązowy; często porasta glonami, nabiera zielonkawego odcienia co stanowi dodatkowy kamuflaż. Kończyny posiadają tylko 2 palce zakończone haczykowatymi pazurami. Jest świetnym pływakiem.", "category": "Fauna Ameryki Południowej", "icon": "Len" }, "geometry": { "type": "Point", "coordinates": [ 16.995360197527827, 52.399715265921657 ] } },
{ "type": "Feature", "properties": { "fid": 8, "name": "Bolita południowa", "comments": "Bolita południowa i blisko spokrewniona z nią bolita brazylijska, to gatunki endemiczne dla Ameryki Południowej. Oznacza to, że w środowisku naturalnym nie występują nigdzie indziej na świecie. Mają silnie rozwinięte pazury i łapy, ale nie wykopują własnych schronień; wykorzystują nory porzucone przez inne gatunki lub zakopują się pod gęstą roślinnością. Zaniepokojone, zwijają się w regularną kulę, pokrytą w całości keratynowym oancerzem - zbudowanym z tej samej substancji co ludzkie włosy i paznokcie. Młode rodzą się ślepe, jednak szybko zdobywają umiejętność chodzenia i zamykania pancerza, co chroni je nie tylko przed atakiem drapieżników, ale i przed utratą ciepła.", "category": "Fauna Ameryki Południowej", "icon": "Pcn" }, "geometry": { "type": "Point", "coordinates": [ 16.99534092768436, 52.399670273950825 ] } },
{ "type": "Feature", "properties": { "fid": 9, "name": "Lemur czerwonobrzuchy", "comments": " Drugą używaną nazwą tego gatunku jest lemuria czerwonobrzucha. Odżywiając się nektarem z różnych roślin, zapyla je. Prowadzi dzienny jak i nocny tryb życia. W pierwszym miesiącu życia matka nosi młode na brzuchu, później przekazuje je samcowi, który nosi je na grzbiecie. Mogą żyć do 20 lat. W wyniku nielegalnych polowań oraz wycinek lasów deszczowych na Madagaskarze są zagrożone wyginięciem.", "category": "Małe ssaki i naczelne", "icon": "Lem" }, "geometry": { "type": "Point", "coordinates": [ 16.995424782137579, 52.399605786120112 ] } },
{ "type": "Feature", "properties": { "fid": 10, "name": "Lis srebrny", "comments": "Lisy uratowane z ferm futrzarskich przez działaczy stowarzyszenia 'Otwarte klatki'. W polsce statystycznie co godzinę dla futra ginie: 9 lisów rudych/polarnych. <br> <img src='./Animal_photos/10.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Lis" }, "geometry": { "type": "Point", "coordinates": [ 16.995737541934059, 52.399571897054877 ] } },
{ "type": "Feature", "properties": { "fid": 11, "name": "Lemur katta", "comments": "Lemury żyją w grupach rodzinnych liczących od 5 do nawet 20 osobników. Chętnie wygrzewają się na słońcu. Długi ogon pomaga lemurowi w utrzymaniu równowagi podczas przemieszczania się i skokach między drzewami. Podobnie jak u ludzi, tak również u lemurów na dłoniach można znaleść linie papilane. Aktywne w ciągu dnia, niestety poważnie zagrożone wyginięciem ze względu na ciągłą degradację środowiska naturalnego. <br> <img src='./Animal_photos/11.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Lem" }, "geometry": { "type": "Point", "coordinates": [ 16.995347787290306, 52.399419327125521 ] } },
{ "type": "Feature", "properties": { "fid": 12, "name": "Saki białolica", "comments": "U tego gatunku występuje wyraźny dymorfizm płciowy, czyli różnice w wyglądzie płci. Samice są szaro-brązowe, a samce czarne, z wyraźnie białym przodem głowy. Prowadzi głównie nadrzewny tryb życia. Tworzy niewielkie stada, zwykle złożone z pary rodziców i ich potomstwa. Pojedyncza grupa może liczyć od 2 do 9 osobników. Świetnie się wspina, a długie kończyny sprawiają, że jest doskonałym skoczkiem. Ze względu na te umiejętności, bywa nazywana 'mono volador' co oznacza 'latająca małpa'. <br> <img src='./Animal_photos/12.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Sab" }, "geometry": { "type": "Point", "coordinates": [ 16.995208865023812, 52.399318331690111 ] } },
{ "type": "Feature", "properties": { "fid": 13, "name": "Wari rudy", "comments": "Największy z rodziny lemurów i jednocześnie najbardziej zagrożony wyginięciem. Komunikuje się za pomocą zróżnicowanych i niekiedy bardzo głośnych dźwięków. W odróżnieniu od pozostałych lemurów, samica zostawia swoje młode w gniździe, a w razie potrzeby przenosi je w pysku. Długi ogon pozwala mu zachować równowagę podczas biegania i skakania na gałęziach. <br> <img src='./Animal_photos/13.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Lem" }, "geometry": { "type": "Point", "coordinates": [ 16.995173922374327, 52.399229601037874 ] } },
{ "type": "Feature", "properties": { "fid": 14, "name": "Wari czarno-biały", "comments": "Występuje w trzech podgatunkach: V.v.variegata (nominatywny), V.v.editorum oraz V.v.subcincta. Mieszkający w Nowym ZOO w Poznaniu, trzeci z wymienionych, charakteryzuje się białym pasem na plecach, oddzielającym czarne łaty. Żyje w parach lub stadach do kilkunastu osobników. Grupą zawsze  dowodzą samice, choć w przeciwieństwie do innych gatunków lemurowatych, samce wari czarno-białego są mniej uległe. Młode tego gatunku są umieszczane w gnieździe i pilnowane przez oboje rodziców. <br> <img src='./Animal_photos/14.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Lem" }, "geometry": { "type": "Point", "coordinates": [ 16.995129730199977, 52.399126761048073 ] } },
{ "type": "Feature", "properties": { "fid": 15, "name": "Orłosęp brodaty", "comments": "Brak opisu", "category": "Sowy i Ptaki Drapieżne", "icon": "Pdr" }, "geometry": { "type": "Point", "coordinates": [ 16.995544097678874, 52.398181811189879 ] } },
{ "type": "Feature", "properties": { "fid": 16, "name": "Flaming czerwonak chilijski", "comments": "Mieszkają w Nowym Zoo od początku lat 70 ubiegłego wieku. W 2005 roku zaczęły wznosić gniazda - kopce z mokrej ziemi. W naturze ptaki żyją w olbrzymich stadach, dlatego w zoo trzeba było 'zagęścić' ich miejsce bytowania odgradzająć teren siatką. U dorosłych osobników zakrzywiony dziób, język i szczęki to aparat filtrujący drobne skorupiaki z mułu. Pisklę po wykluciu ma prostu dziób, dlatego uzależnione jest całkowicie od rodziców, którzy karmią je ptasim mlekiem. <br> <img src='./Animal_photos/16.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Fla" }, "geometry": { "type": "Point", "coordinates": [ 16.997985568072025, 52.396517123657041 ] } },
{ "type": "Feature", "properties": { "fid": 17, "name": "Kob śniady", "comments": "Dorosłe samce są niezwykle terytorialne. Młode osobniki płci męskiej są wyganiane ze stada, kiedy tylko zaczynają wyrastać im rogi. Tworzę wtedy własne stada samców-kawalerów. Jasny pierścień na zadzie pełni podobną rolę, jak 'lustro' u jeleni - pomaga stadu trzymać się razem. Żyją w pobliżu zbiorników wodnych. Woda służy kobom jako schronienie, wbiegają do niej, w czasie ucieczki przed drapieżnikami. Dorosłe samce mogą ważyć do 270 kg. Starcia, w których walczą o terytorium, trwają nawet pół godziny.", "category": "Duże ssaki roślinożerne", "icon": "Kob" }, "geometry": { "type": "Point", "coordinates": [ 16.998633758535906, 52.397717468473815 ] } },
{ "type": "Feature", "properties": { "fid": 18, "name": "Adaks pustynny ", "comments": "Adaksy pozyskują wodę głównie ze zjadanych roślin. Piją bardzo rzadko. Są przystosowane do znoszenia dużych różnic temperatury. Rogi występują zarówno u samców jak i samic; są cylindryczne, skręcone i wygięte ku tyłowi. Tworzą małe stada od 5 do 20 osobników i prowadzą koczowniczy tryb życia. Adaksy wędrują w ślad za opadami deszczu, tam bowim pojawia się roślinność, którą się żywią. Racice adaksów są spłaszczone i szeroko rozstawione. Pomaga im to sprawnie przemieszczać się po piaszczystych obszarach pustyni. <br> <img src='./Animal_photos/18.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Ada" }, "geometry": { "type": "Point", "coordinates": [ 16.997877352947039, 52.39791562969085 ] } },
{ "type": "Feature", "properties": { "fid": 19, "name": "Struś", "comments": "Jeden samiec ma kilka partnerek, które składają jaja do przygotowanego wcześniej gniazda na ziemi. PO złożeniu przez samice jaj samiec zajmuje się ich wysiadywaniem i wychowaniem piskląt. Wykorzystują wodę zawartą w zjadanych roślinach. Posiadają także charakterystyczne dla ptaków morskich gruczoły solne, które pozwalają im korzystać z wody słonej. Są nielotami, ale posiadają potężne skrzydła pozwalające im na szybką zmianę kierunku biegu. Jajko strusia jest największym ptasim jajem. Może ważyć nawet 1,5 kg, a jego objętość odpowiada objętości trzydziestu jaj kurzych.", "category": "Fauna Afryki", "icon": "Str" }, "geometry": { "type": "Point", "coordinates": [ 16.997585479051338, 52.397331176949727 ] } },
{ "type": "Feature", "properties": { "fid": 20, "name": "Zebra pręgowata", "comments": "Nazywane są również zebrami Grevy'ego. Są największymi zebrami i największymi dzikimi koniowatymi. Są też najgęściej prążkowane ze wszytskich zebr. Nowo urodzone źrebięta mają pasy brązowo-czarne, a ich grzywy ciągną się zdłuż grzbietu aż do ogona. Tworzą duże stada, często mieszane z żyrafami, antylopami, strusiami oraz gnu. Skubią suche, stwardniałe wierzchołki traw, które są zbyt twarde, aby mogły zostać strawione przez innych roślinożerców.", "category": "Fauna Afryki", "icon": "Zeb" }, "geometry": { "type": "Point", "coordinates": [ 16.996713968264174, 52.397697401465841 ] } },
{ "type": "Feature", "properties": { "fid": 21, "name": "Gnu brunatne ", "comments": "W wyniku polowań prawie całkowicie wyginęły, obecnie ich liczba wzrasta dzięki reintrodukcjom i ochronie. Samce są terytorialne - pilnują obszaru, na którym pasie się stado samic. Młode samce funkcjonują w oddzielnych grupach. Podobni jak gnu pręgowane migrują w stadach. Z powodu charakterystycznego białego ogona, zwane też gnu białoogonowym.", "category": "Fauna Afryki", "icon": "Wol" }, "geometry": { "type": "Point", "coordinates": [ 16.99667285926477, 52.397153080379866 ] } },
{ "type": "Feature", "properties": { "fid": 22, "name": "Tapir anta", "comments": "Krótka trąbka, to nos zrośnięty z górną wargą. Pełni funkcje 'rurki do nurkowania' - umożliwia oddychanie, gdy reszta ciała tapira jest zanurzona pod powierzchnią wody; pomaga również w zrywaniu i chwytaniu pożywnienia. Są doskonałymi pływakami i świetnie nurkują. W przypadku niebezpieczeństwa, chowają się w wodzie. Pod powierzchnią mogą wytrzymać nawet kilka minut. U młodych osobników występuje charaklterystyczne, paskowane umaszczenie, pomagające w kamuflażu. Pręgi i cętki zanikają wraz z wiekiem. Są spokrewnionez koniami, zebrami i nosorożcami.", "category": "Fauna Ameryki Południowej", "icon": "Tap" }, "geometry": { "type": "Point", "coordinates": [ 16.999253476701792, 52.397293550983591 ] } },
{ "type": "Feature", "properties": { "fid": 23, "name": "Nandu szare", "comments": "Wysiadywaniem jaj oraz opieką nad młodymi zajmuje się wyłącznie samiec. Podczas jednego lęgu, może mieć pod opieką od 10 do 30 jaj, pochodzących od różnych samic. Nandu nie potrafią latać. Mają jednak grube, umięśnione i silne nogi, umożliwiające szybką ucieczkę lub obronę przed napastnikiem. Pióra nie służą im do latania. Mają charakter okrywowy, przypominają nieco sierść. Pomagają w regulacji temperatury ciała. <br> <img src='./Animal_photos/23.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Fauna Ameryki Południowej", "icon": "Emu" }, "geometry": { "type": "Point", "coordinates": [ 16.999773505544134, 52.397129250506239 ] } },
{ "type": "Feature", "properties": { "fid": 24, "name": "Mara patagońska", "comments": "Mary nie należą do zajęczaków. Są gryzoniami, mimo, że zewnętrznie przypominają zajęce lub króliki. Poruszają sięna czterech kończynach inochodem lub podskakują. Są zwierzętami monogamicznymi - łączą się w pary na całe życie. Nowego partnera znajdują tylko w przypadku śmierci poprzedniego. Samce wędrują za samicami. Samiec oznacza partnerkę swoim moczem, a teren wokół niej również kołem. Tworzy w ten sposób ruchome terytorium. Tworzą ' żłobki' w wykopanych norach. Młode wielu par są pilnowane i karmione przez samice, które zmieniają się co około godzinę, podczas gdy reszta rodziców żeruje w okolicy.", "category": "Fauna Ameryki Południowej", "icon": "Mar" }, "geometry": { "type": "Point", "coordinates": [ 17.000270924436819, 52.397040829003757 ] } },
{ "type": "Feature", "properties": { "fid": 25, "name": "Kapibara wielka", "comments": "Jest największym gryzoniem świata. Może ważyć nawet ponad 60 kg i mierzyć do 130 cm długości. Jest spokrewniona z kawią domową. Świetnie pływa i nurkuje - potrafi wstrzymać oddech do 5 minut. Większość czasu spędza blisko zbiorników wodnych i ukrywa się w gęstej roślinności. Zaniepojona ucieka do wody. Żyje w grupach do kilkudziesięciu osobników. Kapibary komunikują się między sobą dźiękami, podobnymi do tych wydawanych przez kawie domowe.", "category": "Fauna Ameryki Południowej", "icon": "Kapi" }, "geometry": { "type": "Point", "coordinates": [ 17.000712846180313, 52.397091624356634 ] } },
{ "type": "Feature", "properties": { "fid": 26, "name": "Czepiak czarnoręki", "comments": "Posiada długi, chwytny ogon, który osiąga do 85 cm. Tą 'piątą kończyną' czepiak podnosi przedmioty i asekuruje się podczas przemieszczania pod rzewach. Może też na nim zawisnąć, utrzymując cały ciężar swojego ciała. Dłonie z czterema palcami umożliwiają zminne i szybkie odbijanie się od gałęzi drzew. Nie posiada kciuka - w utrzymaniu równowagi pomaga ogon. Żyje w rodzinnych grupach; każda z nich ma swoje terytorium, po którym porusza się nadrzewnymi szlakami. Czasami schodzi na ziemię, gdzie dobrze chodzi i biega na dwóch nogach.", "category": "Fauna Ameryki Południowej", "icon": "Mal" }, "geometry": { "type": "Point", "coordinates": [ 17.001121880724288, 52.397252162371359 ] } },
{ "type": "Feature", "properties": { "fid": 27, "name": "Ostronos białonosy", "comments": "Bez problemu schodzą z drzew, skierowane głową w dół dzięki łokciom, które mogą obracać się o 180°. Prowadzą dzienny tryb życia. Samice z młodymi tworzą stada. Ogon ułatwia utrzymanie równowagi podczas wspinaczki po drzewach. Długi pysk ułatwia pozyskiwanie pożywienia w trudno dostępnych miejscach. W poszukiwaniu jedzenia są w stanie przemierzyć do 2 km.", "category": "Małe ssaki i naczelne", "icon": "Osb" }, "geometry": { "type": "Point", "coordinates": [ 17.001350451760928, 52.397671743153424 ] } },
{ "type": "Feature", "properties": { "fid": 29, "name": "Niedźwiedź brunatny ", "comments": "Niedźwiedzie są zwolennikami najmniejszego wysiłku. Ich dieta zależna jest od pory roku: zdecydowaną większość niedźwiedziej diety stanowią rośliny. Dzięki badaniom za pomocą telemetrii radiowej oraz systemowi informacji geograficznej (GIS) zbiera się informację o wędrówkach niedźwiedzi i zasiedlaniu nowych obszarów. Niedźwiedzie często wędrują na duże odległości, potrafią przemieszczać się w ciągu tygodnia nawet o kilkaset kilometrów przekraczając granice różnych krajów. <br> <img src='./Animal_photos/29.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Niedźwiedzie", "icon": "Nib" }, "geometry": { "type": "Point", "coordinates": [ 17.003012509299545, 52.397970382544152 ] } },
{ "type": "Feature", "properties": { "fid": 30, "name": "Szkockie bydło wyżynne", "comments": "Jedna ze starszych ras bydła domowego, pochodząca z terenów północnej Szkocji. Długowieczna i niezwykle odporna na trudne i zmienne warunki środowiska. Przed zimnem nie chroni jej tłuszcz, a gruba, gęsta i długa sierść. Z tego względu, jest chętnie chodowana w kierunku mięsnym. Natomiast jej urokliwy wygląd oraz spokojny i łagodny charakter, stał się powodem rosnącej popularności tej rasy w gospodarstwach agroturystycznych. <br> <img src='./Animal_photos/30.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Wol" }, "geometry": { "type": "Point", "coordinates": [ 17.003038202424161, 52.398778067423528 ] } },
{ "type": "Feature", "properties": { "fid": 31, "name": "Wilk", "comments": "W latach 90-tych populacja wilka liczyła 300 - 400 osobników zamieszkujących głównie Karpaty i wschodnią granicę kraju. Po objęciu gatunku ścisłą ochroną w 1998 r. wilki stopniowo powróciły do centralnej i zachodniej Polski, zajmując opuszczone zbiorowiska leśne. Obecnie w Polsce żyje ponad 2 tys. tych ssaków. Wilki wyruszają na łowy najczęściej o zmierzchu. Zazwyczaj dzielą się na małe podgrupy i rozchodzą po swoim ogromnym terytorium. Wyciem (słyszalnym z odległości 10 km) komunikują sięreszcie rodziny m.in. rezultat polowania, swoją lokalizację, czy potencjalne niebezpieczeństwo. Wspólne wycie grupy służy też budowaniu więzi. <br> <img src='./Animal_photos/31.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Wilki", "icon": "Wlk" }, "geometry": { "type": "Point", "coordinates": [ 17.004755010773582, 52.399246211370702 ] } },
{ "type": "Feature", "properties": { "fid": 32, "name": "Tygrys", "comments": "Tygrys prowadzi samotniczy tryb życia tylko w okresie godów samiec przebywa kilka dni w towarzystwie samicy. Tygrysy są największymi kotami na Ziemi. Długość ich ciała wraz z ogonem to prawie 4 metry a ich kły mogą mieć imponującą długość 7,5 cm. Potrafią unieść w pysku 70 kg, skoczyć w dal na 6 m a wzwyż nawet 2m. Gdy jest bardzo głodny, może zjeść nawet 35 kg mięsa. <br> <img src='./Animal_photos/32.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Tygrysy", "icon": "Tyg" }, "geometry": { "type": "Point", "coordinates": [ 17.006470803873619, 52.399747520590239 ] } },
{ "type": "Feature", "properties": { "fid": 33, "name": "Słoniarnia", "comments": "Słoń ma 4 metry wysokości w kłębie i waży około 6 ton. W ciągu doby potrafi zjeść od 70 do 150 kg pożywnienia. Słonie żyją 70-80 lat. W ciągu doby potrafi pokonać dystanś 100 km. <br> <img src='./Animal_photos/33.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Słonie", "icon": "Sln" }, "geometry": { "type": "Point", "coordinates": [ 17.006896282017358, 52.398533506015902 ] } },
{ "type": "Feature", "properties": { "fid": 34, "name": "Oryks południowy ", "comments": "Oryksy są w stanie obyć się bez wody kilka dni i jednocześnie są prawdziwymi mistrzami w jej poszukiwaniu. Rogi występują zarówno u samców, jak i u samic, a ich długość może sięgać nawet 120 cm. W stadzie obowiązuje ścisła hierarchia, a pieczę nad nim sprawuje jeden dominujący i bardzo terytorialny samiec. Potrafią sokopać się do wody przednimi racicami wyczuwając ją pod piasykiem, w wyschniętych korytach rzek. <br> <img src='./Animal_photos/34.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Ork" }, "geometry": { "type": "Point", "coordinates": [ 17.009537091912705, 52.400450088071636 ] } },
{ "type": "Feature", "properties": { "fid": 35, "name": "Suseł moręgowany", "comments": "Susły moręgowane wymarły w Polsce w latach 70-tych. Dzięki staraniom PTOP Salamandra oraz UAM i Nowemu Zoo, od 2005 roku trwa proces reintrodukcji susłów w naszym kraju. Często stoją na tylnich łapach, uważnie obserwując otoczenie. Gdy zauważą niebezpieczeństwo, ostrzegają resztę kolonii donośnym dźwiękiem, po czym chowają się do nory. Hibernują od października do marca. Zimę są w stanie przetrwać, dzięki zapasom tłuszczu, zgromadzonym latem i wczesną jesienią. Każdy osobnik hibernuje samotnie, w osobnej norze.", "category": "Małe ssaki i naczelne", "icon": "Sus" }, "geometry": { "type": "Point", "coordinates": [ 17.011464626626893, 52.400664571086025 ] } },
{ "type": "Feature", "properties": { "fid": 36, "name": "Żyrafa północna", "comments": "Żyrafy to najwyższe współrześnie żyjące ssaki, Sama żyrafia szyja może mieć 2 metry długości. Samce są w stanie osiągnąć blisko 6 metrów wzrostu i ważyć 1200 kg. Podstawą diety żyraf są liści i hałązki. Długie nogi i szyja umożliwiają im dotarcie do pożywiewnia. <br> <img src='./Animal_photos/36.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Żyrafy", "icon": "Zyr" }, "geometry": { "type": "Point", "coordinates": [ 17.011950633492955, 52.399243357435942 ] } },
{ "type": "Feature", "properties": { "fid": 37, "name": "Nosorożec czarny", "comments": "Nosorożce czarne odżywiają się liśćmi, gałązkami i wierzchołkami traw. Ich pysk jest przystosowany do skubania: trójkątna górna warga zachodzi na dolną. Ogród zoologiczny w Poznaniu jest JEDYNYM w Polsce, w któreym mieszkają dwa gatunki nosorożców. <br> <img src='./Animal_photos/37.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Nosorożce", "icon": "Ns" }, "geometry": { "type": "Point", "coordinates": [ 17.010084284920428, 52.399022627475709 ] } },
{ "type": "Feature", "properties": { "fid": 38, "name": "Tamandua południowa", "comments": "Tamandua południowa i północna należą do mrówkojadowatych. W przeciwieństwie do większego przedstawiciela tej rodziny: mrówkojada wielkiego, większość dnia spędzają na drzewach. Do rozkopywania mrowisk i termitier służą im cztery potężne pazury na każdej z przednich łap. Przydają się one również do obrony. Tamanduy częściej aktywne są po zmroku, większość dnia przesypiają na gałęziach drzew, czasem w wykopanych przez inne zwierzęta norach. Proawdzą samotniczy tryb życia. <br> <img src='./Animal_photos/38.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Mkj" }, "geometry": { "type": "Point", "coordinates": [ 17.011179805115496, 52.401108963841757 ] } },
{ "type": "Feature", "properties": { "fid": 39, "name": "Wielbłąd dwugarbny", "comments": "Wielbłąd dwugarbny zwany jest również baktrianem. Przystosował się do życia w trudnych warunkach jakie panują na pustyni. W garbach gromadzone są zapasy pokarmowe w postaci tłuszczu - nawet do 40 kg! Dzięki temu może obyć się bez pokarmu nawet kilkanaści dni. Jednorazowo może wypić 120 l wody. Oczy wielbłąda zabezpieczone są przed piaskiem długimi, kręconymi rzęsami. Dodatkowo posiadają trzecią powiekę, która usuwa nadmiar piasku. Nos zamykany jest specjalnymi mięśniami co uniemożliwia dostanie się piasku do nozdrzy. <br> <img src='./Animal_photos/39.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Wielbłądy", "icon": "Wbl" }, "geometry": { "type": "Point", "coordinates": [ 17.012353501687024, 52.400866190400308 ] } },
{ "type": "Feature", "properties": { "fid": 40, "name": "Wikunia andyjska", "comments": "Najmniejszy przedstawiciel rodziny wielbłądowatych, blisko spokrewniona z guanako. Jest dzikim podgatunkiem alpaki. Serce wikunii jest bardzo duże - o połowę większe niż u innych zwierząt tej samej wielkości. Umożliwia organizmowi prawidłowy i wydajny transport tlenu, mimo przebywania na dużych wysokościach. Obecnie, wikunie są chronione prawem, tak jak miało to miejsce za czasów Inków. Niestety, w międzyczasie liczebność ich populacji zmniejszyła się na skutek licznych polowań. <br> <img src='./Animal_photos/40.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Fauna Ameryki Południowej", "icon": "Wa" }, "geometry": { "type": "Point", "coordinates": [ 17.011699868596644, 52.401405449347479 ] } },
{ "type": "Feature", "properties": { "fid": 41, "name": "Lew", "comments": "Błędnie nazywany 'królem dżungli' - większość czasu spędza na otwartych terenach sawannowych. U tego gatunku występuje dymorfizm płciowy - samce są większe i cięższe od samic, większość z nich posiada też grzywę, porastającą głowę, kark i pierś. Jest jedynym kotowatym, tworzącym stada. Grupa składa się z kilku spokrewnionych lwic, osobników młodocianych oraz 1-4 niespokrewnionych samców. W grupie rodzinnej polowaniem zajmują się głównie samice. Zadaniem samców jest ochrona terytorium i reszty stada przed obcymi lwami lub innymi drapieżnikami. <br> <img src='./Animal_photos/41.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Lwy", "icon": "Lew" }, "geometry": { "type": "Point", "coordinates": [ 17.012830366079999, 52.401525841142124 ] } },
{ "type": "Feature", "properties": { "fid": 42, "name": "Urson amerykański ", "comments": "Większą część życia spędza na drzewach, ale jest też świetnym pływakiem. Wierzchnia część ciała ursona jest pokryta kolcami wyposażonymi dodatkowo w zadziory, które łatwo się łamią. W ciągu dnia odpoczywa w jaskiniach lub norach. Zimą nie zapada w sen zimowy.", "category": "Małe ssaki i naczelne", "icon": "Ura" }, "geometry": { "type": "Point", "coordinates": [ 17.011806751995071, 52.401861933165911 ] } },
{ "type": "Feature", "properties": { "fid": 43, "name": "Bizon amerykański ", "comments": "Brak opisu <br> <img src='./Animal_photos/43.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Bzn" }, "geometry": { "type": "Point", "coordinates": [ 17.012206412279696, 52.402856113780345 ] } },
{ "type": "Feature", "properties": { "fid": 44, "name": "Makak japoński ", "comments": "Występuje w japońskiej mitologii, literaturze i sztuce. Jest bardzo inteligentny, szybko uczy się nowych zachowań, które przekazuje następnym osobnikom. Znoszą mrów od -20°C stąd też niektóre grupy makaków nauczyły się korzystać z ciepłych żródeł podczas mroźnych zim. Posiadają wyraźnie zaznaczoną hierarchię, zarówo wśród samców jak i samic.", "category": "Małe ssaki i naczelne", "icon": "Mal" }, "geometry": { "type": "Point", "coordinates": [ 17.006322609648578, 52.402118726652979 ] } },
{ "type": "Feature", "properties": { "fid": 45, "name": "Pelinkany ", "comments": "Są znakomitymi pływakami. Posiadają błonę pławną spinającą wszystkie palce stopy oraz charakterystyczną kieszeń skórną pod żuchwą. Ich dzioby mierzą do 50 cm. Urządzają łowy zbiorowe, formując na powierzchni wody półkole i zapędzają stada ryb na płycizny, gdzie otaczają je i wybierają z wody. Gniazdują w dużych koloniach.", "category": "Ptaki ozdobne i wodne", "icon": "Plk" }, "geometry": { "type": "Point", "coordinates": [ 17.005134018211884, 52.400659348566009 ] } },
{ "type": "Feature", "properties": { "fid": 46, "name": "Kacyk ochrowy", "comments": "Jest endemitem wyspy Montserrat, czyli nie występuje nigdzie indziej na świecie. Szacuje się, że na wolności nie pozostało więcej niż 460 osobników. Jest symbolem wyspy Montserrat. Obszar występowania gatunku jest niewielki, ograniczony do zaledwie 102 km². U tego gatunku występuje dymorfizm płciowy. Upierzenie samic jest głównie zielonożółte i oliwkowe; a u samców - czarne, z żółtopomarańczowym brzuchem.", "category": "Inne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 17.000477240227511, 52.399575508482471 ] } },
{ "type": "Feature", "properties": { "fid": 47, "name": "Puchoczub", "comments": "U tego gatunku występuje dymorfizm płciowy. Samica jest brązowo-zielona, a upierzenie samca  ciemne, z okazałym, czerwonym czubem na głowie. Żeruje głównie na ziemi, rzadko korzysta z możliwości lotu. W przeciwieństwie do innych kurowatych, pisklęta są karmione przez rodziców z dzioba do dzioba zanim nauczą się grzebać. Zwany jest czasem bezszponem. Nazwa jest adekwatna, posiada on bowiem pazury, a na nogach samców występują ostrogi.", "category": "Inne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 17.000489829858576, 52.399641585666785 ] } },
{ "type": "Feature", "properties": { "fid": 48, "name": "Sorkonos czarno-rdzawy ", "comments": "Gatunek słabo poznany przez naukę, ze względu na skryry tryb życia. Ma wspólnego przodka ze słoniami, nie, jak by się mogło wydawać - z ryjówkami. Giętki i długi pysk zakończony jest nosem o doskonałym węchu. Zwierzę porusza się nim niezależnie od reszty ciała. Jest monogamiczny. Para żyje na tym samym terenie, ale bliższe relacje nawiązuje jedyniew celach rozrodczych. Jest aktywny w ciągu dnia.", "category": "Inne", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.000494968483501, 52.39969998119809 ] } },
{ "type": "Feature", "properties": { "fid": 49, "name": "Gereza białobroda", "comments": "Dłonie gerezy mają tylko 4 palce - gdyż kciuk jest silnie zredukowany. Wynika to z anatomicznego przystosowania do szybkiego poruszania się w koronach drzew. Prowadzą dzienny, nadrzewny tryb życia. Czasami w poszukiwaniu jedzenia schodzą na ziemię. Posiadają długie białe ogony zakończone puszystą kitą (od 52 do 100 cm). Małpy tego gatunku żyją w stadach złożonych z kilkunastu osobników. Choć dorosłe małpy są czarno-białe, młode gerezy rodzą się całkowicie białe. <br> <img src='./Animal_photos/49.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Mal" }, "geometry": { "type": "Point", "coordinates": [ 16.999821808618407, 52.398862527017947 ] } },
{ "type": "Feature", "properties": { "fid": 50, "name": "Koziorożec nubijski ", "comments": "Jednym z głównych zagrożeń koziorożca nubijskiego jest utrata siedlisk, a także występujące drapieżniki. Rogi występują u obu płci, rogi samic są znacznie mniejsze niż samców. U samców dorastają do około 1 metra długości. Mimo pustynnego środowiska życia bardzo ważne dla koziorożców jest codzienny dostęp do wody. Krótka i gładka sierść pozwala na odbicie dużej ilości promieni słonecznych, dzięki czemu koziorożce mogą vyć aktywne w ciągu dnia, nawet podczas dużych upałów. <br> <img src='./Animal_photos/50.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Kzr" }, "geometry": { "type": "Point", "coordinates": [ 16.999515546572923, 52.39856027458228 ] } },
{ "type": "Feature", "properties": { "fid": 51, "name": "Pandka ruda", "comments": "Nazwa 'panda' pochodzi od nepalskich słów 'nigalya ponya' co oznacza jedząca banbus. W naturze, roślina ta stanowi aż 95% diety pandki rudej. Pandka ruda jest bliżej spokrewniona z szopami, skunksami i łasicami, niż z niedźwiedziami. Naukowcy odkryli ten gatunek blisko 50 lat wcześniej, niż pandę wielką. Większość czsu spędza w koronach drzew, z których schodzi głową w dół. We spinaczce pomagają częściowo wysunięte pazury. Spodnia część łapy pokryta jest gęstym futrem. <br> <img src='./Animal_photos/51.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "Pan" }, "geometry": { "type": "Point", "coordinates": [ 17.000067075441056, 52.399911706385083 ] } },
{ "type": "Feature", "properties": { "fid": 52, "name": "Takin złoty", "comments": "Takin występuje w 4 podgatunkach. W Nowym Zoo mieszka jeden z nich - takin złoty. Mimo krępej budowy ciała, doskonale poruszają się po górskich zboczach. Uciekając przed drapieżnikiem, są w stanie wspiąć się po niemal pionowej skale. Wiosną i latem tworzy duże stada i żeruje wysoko w górach. Jesienią i zimą dzieli się na małe grupy, a pożywienia szuka w dolinach. Jest aktywny głównie o świcie i zmierzchu. Często odwiedza lizawki solne, co czyni go podatnym na ataki kłusowników. Przez człowieka zabijanie są głównie dla rogów i mięsa. <br> <img src='./Animal_photos/52.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Wol" }, "geometry": { "type": "Point", "coordinates": [ 16.999770984083835, 52.400359575775973 ] } },
{ "type": "Feature", "properties": { "fid": 53, "name": "Nandinia palmowa", "comments": "Jest jedym z niewielu kotowatych , potrafiącuch schodzić z drzewa głową w dół. Długi ogon pomaga w utrzymaniu równowagi. Choć nie jest chwytny, nandinia może owinąć go wokół gałęzi, co zapobiega upadkowi. Jest zwierzęciem dość skrytym, aktywnym głównie przed świtem i o zmierzchu. Pozostałą część czasu ukrywa się w koronach drzew. Na ziemię schodzi jedynie w poszukiwaniu pożywienia. Potrafi doskonale wspinać się i skakać (do 1,8m wzwyż i 1m wzdłuż). Jak większość kotowatych, prowadzi samotniczy tryb życia. Zdarza jej się jednak tworzyć niewielki grupy bez wyraźnych więzi.", "category": "Małe ssaki drapieżne", "icon": "Mlssk" }, "geometry": { "type": "Point", "coordinates": [ 16.999713779644246, 52.401056264896312 ] } },
{ "type": "Feature", "properties": { "fid": 54, "name": "Ocelot nadrzewny", "comments": "Często spotykany również pod nazwą margaj. Potrafi obrócić staw skokowy o 180°, dzięki czemu chwyta gałęzie zarówno przednią, jak i tylną łapą. Mobilne stawy umożliwiają mu zejście z drzewa głową w dół - przeciwnie do większości kotowatych. Większość czasu spędza odpoczywając w koronach drzew. Potrafi szybko skakać z gałęzi na gałąź w pogoni za ofiarą. W utrzymaniu równowagi pomaga mu ogon. Szczątki tego gatunku znalezione na terenie Południowych Stanów Zjednoczonych sugerują, że dawniej zasięg występowania margaja był znacznie większy.", "category": "Małe ssaki drapieżne", "icon": "Ocl" }, "geometry": { "type": "Point", "coordinates": [ 16.999828043102998, 52.400996953552486 ] } },
{ "type": "Feature", "properties": { "fid": 55, "name": "Mangusta karłowata", "comments": "Jest najmniejszym mięsożercą Afryki. Rolę dominującą obejmuje samica, zaś w stadzie przeżywa tylko potomstwo pary alfa (najczęściej najstarszy samiec i samica). Dzięki grubej sierści a także posiadanym receptorom acetylocholiny są odporne na jad węży. Węże są głównym celem ich polowań. Aktywne w ciągu dnia. Żwyją w grupach rodzinnych, liczących do 30 osobników. W stadzie panuje ścisła hierarchia. <br> <img src='./Animal_photos/55.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki drapieżne", "icon": "Mlssk" }, "geometry": { "type": "Point", "coordinates": [ 16.999980419577362, 52.401001779573235 ] } },
{ "type": "Feature", "properties": { "fid": 56, "name": "Żeneta tygrysia", "comments": "Żenety tygrysie prowadzą głównie nocny tryb życia. W ciągu dnia śpią wysoko na drzewach, półkach skalnych i w jaskiniach. Przemieszczają się przede wszystkim nad ziemią - świetnie wspinają się po drzewach. Po gałęziach, żenety chodzą nisko, na ugiętych łapach, by zachować równowagę. W przypadku zachwiania, odchylają nogi na boki. Rośliny zjadane przez żenety nie są trawione. Służą wywołaniu wymiotów, w celu pozbycia się z żołądka toksyn, niestrawionych złogów sierści i resztek piół. Ciężarne samice budują gniazda w dziuplach wysokich drzew, podziemnych norach lub wśród głazów. Rodzą zazwyczaj dwójkę młodych.", "category": "Małe ssaki drapieżne", "icon": "Znt" }, "geometry": { "type": "Point", "coordinates": [ 16.999864446210275, 52.401067636345296 ] } },
{ "type": "Feature", "properties": { "fid": 57, "name": "Norka europejska", "comments": "Aktywna o zmierchu i w nocy. Dzień spędza w ukryciu w norach lub pod korzeniami. W Polsce chroniona prawnie, poprzez zakaz fotografowania; filmowania i obserwacji mogących powodować płoszenie lub niepokojenie zwierzącia. Gatunek obecnie jest na skraju wymarcia. Zniknął już niemal z całego obszaru historycznego występowania, który obejmował znaczny obszar Europy - w tym Polskę. Bardzo dobrze pływa, stąd spotykana jest w pobliżu rzek i potoków do 100 metrów od wody. Rzadziej występuje na brzegach jezior.", "category": "Małe ssaki drapieżne", "icon": "Mlssk" }, "geometry": { "type": "Point", "coordinates": [ 17.000038833648116, 52.400967214822494 ] } },
{ "type": "Feature", "properties": { "fid": 58, "name": "Łasica syberyjska", "comments": "Według chińskich legend jest istotą, która może wstępować w ludzkie ciało, kradnąc jednocześnie zamieszkującą je duszę. Wykorzystywana jest do zwalczania populacji gryzoni oraz jako zwierzę futerkowe. Jest aktywna przeważnie wieczorem i nocą. Porusza się głównie po ziemi. Doskonale się wspina i pływa, co wykorzystuje, gdy czuje się zagrożona. Często buduje gniazda w opuszczonych norach. Może wykorzystywać ich kilka na raz - jedna przeznaczona jest do rozrodu, pozostałe pełnią funkcję schronienia. Podobnie do skunksa, w sytuacji silnego zagrożenia, potrafi wystrzelić z gruczołów okołoodbytowych substancję o gryzącym, nieprzyjemnum zapachu.", "category": "Małe ssaki drapieżne", "icon": "Mlssk" }, "geometry": { "type": "Point", "coordinates": [ 16.999955792334855, 52.400949029002646 ] } },
{ "type": "Feature", "properties": { "fid": 59, "name": "Binturong orientalny", "comments": "Binturongi prowadzą głównie nadrzewny tryb życia. We wspinaczce po drzewach, pomagają im zakrzywione i duże pazury. Ślina binturongów ma silne właściwości odkażające. Po nałożeniu na ranę, znacznie przyspiesza się czas jej gojenia. Według badań (wg. Duke University) zapach binturonga zbliżony jest do zapachu popcornu z masłem. W moczu binturonga występuje ten sam związek chemiczny co w prażonej kukurydzy. Długi i zwinny ogon ułatwia binturongom przemieszczanie się wśród drzew, a także zwisanie z gałęzi.", "category": "Małe ssaki drapieżne", "icon": "Mlssk" }, "geometry": { "type": "Point", "coordinates": [ 17.000033194477631, 52.401130940026924 ] } },
{ "type": "Feature", "properties": { "fid": 60, "name": "Otocjon wielkouchy ", "comments": "Posiada 48 zębów - to najwięcej ze wszystkich ssaków. Przedstawiciel rodziny psowatych, ze względu na budowę ciała a także wielkie uszy nazywany jest 'lisil nietoprzem'. Nazwa otocjan pochodzi z języka grackiego: otus czyli uszy oraz cyon czyli pies. Uszy umożliwiają zarejestrowanie dźwięków tak delikatnych, jak ruch owadów znajdujących się pod ziemią. <br> <img src='./Animal_photos/60.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki drapieżne", "icon": "Otc" }, "geometry": { "type": "Point", "coordinates": [ 17.000162534520133, 52.40125018271614 ] } },
{ "type": "Feature", "properties": { "fid": 61, "name": "Jaguarundi", "comments": "Jaguarundi nieźle pływają. Prowadzą raczej dzinny tryb życia, ale bywają aktywne także nocą. W południe wychodzą do wodopoju. Mimo że koty te nie stanowią obiektu polowań dla futra, są poważnie zagrożone poprzez degradację swojego środowiska naturalnego. <br> <img src='./Animal_photos/61.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki drapieżne", "icon": "Jg" }, "geometry": { "type": "Point", "coordinates": [ 17.000497715201131, 52.401342296378182 ] } },
{ "type": "Feature", "properties": { "fid": 62, "name": "Karakal stepowy", "comments": "Nazwa wywodzi się od tureckiego słowa karakulak (czarne ucho). Jest blisko spokrewniony z rysiem (przez co nazywany jest również rysiem stepowym). Ich aktywność (dzienna lub nocna) uzależniona jest od obszaru ich występowania. Przy temparaturze powyżej +10°C. W naturze są to zwierzęta samotnicze - samce i samice bytują na sąsiadujących terenach, w okresie godów łączą się w pary, po czym znów się rozstają. W warunkach wiwaryjnych (na przykład w ZOO) pary mocno zżywają się ze sobą. <br> <img src='./Animal_photos/62.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki drapieżne", "icon": "Kar" }, "geometry": { "type": "Point", "coordinates": [ 17.000336061317565, 52.401405375827594 ] } },
{ "type": "Feature", "properties": { "fid": 63, "name": "Surykatka ", "comments": "Surykatki posiadają wysoką odporność na jad wielu gatunków węży i skorpionów. Potrafią doskonale kopać. Tworzą złożony system nor, posiadający wiele wyjść i mogący sięgać nawet 5 metrów w głąb ziemi. Podczas poszukiwania pożywienia grupa surykatek posiada swoich strażników, gdy dostrzegą zagrożenie szczekają lub gwiżdżą informując o rodzaju niebezpieczeństwa. Dzięki czarnym 'okularom' woków oczu stojąca na tylnych łapkach surykatka może zauważyć drapieżnika z odległości 300 metrów. <br> <img src='./Animal_photos/63.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki drapieżne", "icon": "Sur" }, "geometry": { "type": "Point", "coordinates": [ 17.000560829468906, 52.401616815595006 ] } },
{ "type": "Feature", "properties": { "fid": 64, "name": "Kotek amurski", "comments": "Kotek amurski jest 1 z 10 podgatunków kotka bengalskiego. W przeciwieństwie do większości kotowatych, samce pomagają w opiece nad swoim potomstwem. Dzięki doskonałym umiejętnościom wspinaczki, skutecznie polują na ptaki i nietoperze. Aktywne przede wszystkim nocą, w ciągu dnia obserwować je można tylko gdy temperatura nie przekracza +35°C", "category": "Małe ssaki drapieżne", "icon": "Kot" }, "geometry": { "type": "Point", "coordinates": [ 17.000373980441822, 52.401554060874084 ] } },
{ "type": "Feature", "properties": { "fid": 65, "name": "Manul", "comments": "Prowadzi nocny tryb życia. W dzień odpoczywa ukryty w jaskiniach, szczelinach skalnych lub opuszczonych norach. Wrażenie 'pulchności' powoduje bardzo gęste futro. Jest ono najgęstrze i najdłuższe pośród wszystkich kotów. Manul potrafi wytrzymać temperaturę do -50°C.", "category": "Małe ssaki drapieżne", "icon": "Man" }, "geometry": { "type": "Point", "coordinates": [ 17.000525359311595, 52.401697137813848 ] } },
{ "type": "Feature", "properties": { "fid": 67, "name": "Bielik amerykański ", "comments": "Ciało pokrywa około 7000 piór. Kiedy straci lotkę na jednym skrzydle, traci również odpowiadające jej pióro na drugim. co pozwala zachować równowagę w czasie lotu. Gniazda bielików osiągają masę do 2 ton i średnicę 2 metrów. Największe gniazdo znalezione na Florydzie w 1963 roku miało 3 metry szerokości i 6 metrów głębokości. Szybuje unosząc się w słupach ciepłego powietrza. Pomaga mu to nabrać prędkości nawet do 70 km/h. W większości przypadków tworzy pary na całe życie. <br> <img src='./Animal_photos/67.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Sowy i Ptaki Drapieżne", "icon": "Pdr" }, "geometry": { "type": "Point", "coordinates": [ 17.001632673823259, 52.401884913098719 ] } },
{ "type": "Feature", "properties": { "fid": 68, "name": "Puchacz", "comments": "Charakterystyczny 'pędzel' pełni rolę odbiornika, wyłapując dźwięki z otoczenia, które dopiero potem trawiają co otworu słuchowego. Podobnie jak większość sów potrafią obrócić głowę o 270°C. Jest największą sową występującą w Europie. Samiec odzywa się podwójnym głębokim huknięciem, słyszanym z odległości 1 km.", "category": "Sowy i Ptaki Drapieżne", "icon": "PSow" }, "geometry": { "type": "Point", "coordinates": [ 17.002610249366175, 52.401998360100713 ] } },
{ "type": "Feature", "properties": { "fid": 69, "name": "Bielik", "comments": "Należy do największych ptaków  szponiastych północnej Europy. Rozpiętość skrzydeł bielika osiąga 220 - 240 cm. U samic rozpiętość ta jest większa, niż u samców. Bielik jest symbolem Wolińskiego Parku Narodowego. W Polsce jest pod ścisłą ochroną. Bielik buduje gniazdo na wysokich drzewach. <br> <img src='./Animal_photos/69.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Sowy i Ptaki Drapieżne", "icon": "Pdr" }, "geometry": { "type": "Point", "coordinates": [ 17.002804970698147, 52.402049445031608 ] } },
{ "type": "Feature", "properties": { "fid": 71, "name": "Żuraw białoszyi", "comments":  "Żurawie, są w Azji symbolem powodzenia i długiego życia. Ptaki z tej rodziny dożywają średnio 20-30 lat, jednak najstarszy znany osobnik żył aż 83 lata. Niektóre żurawie białoszyje wybierają na zimowiska pas strefy zdemilitaryzowanej, oddzielającej Koreę Północną od Południowej. W czasie migracji wędrują dużymi grupami, jednak w okresie lęgowym, ptaki te żyją w parach, każda na swoim terytorium, którego broni. Gdy poczują zagrożenie, szarżują na potencjalnego przeciwnika. Atakując swoim silnym dziobem, celują między innymi w oczy.  <br> <img src='./Animal_photos/71.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Zur" }, "geometry": { "type": "Point", "coordinates": [ 17.003744770941228, 52.402023580453047 ] } },
{ "type": "Feature", "properties": { "fid": 72, "name": "Płomykówka zwyczajna ", "comments":  "Jest najbardziej rozpowrzechnionym na świecie gatunkiem sowy, choć według najnowszych badań jest to kilka odrębnych gatunków, uznawanych dotąd za jeden. Prowadzi głównie nocny tryb życia. Jej oczy są duże i niemal całkowicie czarne - jest to przystosowanie do polowania przy bardzo ogranicznonej ilości światła. Charakteryzuje się dużym zróżnicowaniem odmian barwnych oraz wzorów na piórach lotnych.", "category": "Sowy i Ptaki Drapieżne", "icon": "PSow" }, "geometry": { "type": "Point", "coordinates": [ 17.003565892967131, 52.402152086216901 ] } },
{ "type": "Feature", "properties": { "fid": 73, "name": "Karakara falklandzka", "comments":  "W wyniku długiej izolacji wyspowej ptaki te nie nauczyły się bać człowieka. Atakują nowonarodzone jagnięta i podskubują ranne owce, co spowodowało prześladowanie ich przez farmerów. Bardzo inteligentny ptak drapieżny. Mają doskonały wzrok, dobrze też widzą w nocy. Doskonale rozróżnia kolory, zdarza się, że porywa rzeczy czerwonej barwy. <br> <img src='./Animal_photos/73.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Sowy i Ptaki Drapieżne", "icon": "Pdr" }, "geometry": { "type": "Point", "coordinates": [ 17.004102236331097, 52.402135004050741 ] } },
{ "type": "Feature", "properties": { "fid": 74, "name": "Sowa jarzębata", "comments":  "Przystosowała się do polowania w ciągu dnia. Ma to związek z krtótkimi nocami podczas polarnego lata - czas między zachodem i wschodem słońca jest zbyt krótki, by sowa jarzębata mogła zdobyć odpowiednią ilość pożywienia. Jej pióra są sztywne - z tego względu lata dość głośno. Barwa piór na karku imituje 'drugą twarz', ma to na celu zmylenie ewentalnego napastnika. Sowa jarzębowata jest świetnie przystosowana do polowania zimą. Może usłyszeć ofierę znajdującą się pod śniegiem i 'zanurkować' w zaspy, by złapać zdobycz.", "category": "Sowy i Ptaki Drapieżne", "icon": "PSow" }, "geometry": { "type": "Point", "coordinates": [ 17.004040797297947, 52.402174973254169 ] } },
{ "type": "Feature", "properties": { "fid": 75, "name": "Puszczyk uralski", "comments":  "W Polsce występuje około 340 - 700 par tych sów. Gnieździ się w dziuplach drzew i opuszczonych gniazdach innych ptaków. W upierzeniu brak dymforizmu płciowego, lecz samice są znacznie większe od samców. Ich największa aktywność przypada na marzec-kwiecień.", "category": "Sowy i Ptaki Drapieżne", "icon": "PSow" }, "geometry": { "type": "Point", "coordinates": [ 17.003685592636153, 52.40212548012925 ] } },
{ "type": "Feature", "properties": { "fid": 76, "name": "Puszczyk mszarny", "comments":  "Jedna z największych i najdłużej życących sów na świecie. W ogrodach zoologicnzych jego wiek może siągnąć nawet 40 lat. Prowadzi dzienno-nocny tryb życia. Jest doskonałym łowcą, niezależnie od ilości dostępnego światła. Tę cechę można rozpoznać po mniejszej źrenicy - i co za tym idzie, widocznej tęczówce oka. Ma największą szlarę za wszytskich sów. Szlara, to okrągłe płaskie ułożenie piór z przodu głowy ptaka, które pomaga zbierać nawet najcichsze dźwięki i przekazywać je do otworu usznego pod piórami.", "category": "Sowy i Ptaki Drapieżne", "icon": "PSow" }, "geometry": { "type": "Point", "coordinates": [ 17.003461120436018, 52.402175993307253 ] } },
{ "type": "Feature", "properties": { "fid": 77, "name": "Żubr europejski", "comments":  "Żubry całkowicie wygnęły na wolności na początku lat 20. XX wieku. Udało się rozmożyć osobniki żyjące w niewoli i przywrócić ten gatunek Naturze. Są największymi zwierzętami na kontynencie europejskim. Samice mogą ważyć do 650 kg, a samce nawet do 900 kg. Są zwierzętami stadnymi. Żyją w grupach męskich lub mieszanych. W tym drugim przypadku stadu przewodzi zawsze samica, która wybiera miejsce żerowania. Byki chronią samice i młode. W przypadku linii nizinnej imiona żubrów, zaczynają się od tej samej litery, co nazwa państwa, w których przyszły na świat. Hodowlę wspomaga proawdzenie ksiąg rodowodowych. <br> <img src='./Animal_photos/77.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Zub" }, "geometry": { "type": "Point", "coordinates": [ 17.003340105332921, 52.402614154191482 ] } },
{ "type": "Feature", "properties": { "fid": 78, "name": "Kondor wielki ", "comments":  "Brak opisu <br> <img src='./Animal_photos/78.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Sowy i Ptaki Drapieżne", "icon": "Pdr" }, "geometry": { "type": "Point", "coordinates": [ 17.002925268141862, 52.401964253750656 ] } },
{ "type": "Feature", "properties": { "fid": 80, "name": "Bielik olbrzymi", "comments": "Zwany jest także bielikiem kamczackim oraz orłanem. Jest tym smamym największym przedstawicielem bielików na świecie. Bywa, że wypatruje ryby, kołując 6-7 metrów nad lustrem wody, gdy wypatrzy zdobycz pikuje po nią. Samie są cięższe od zamców, zaś rozpiętością skrzydeł potrafi osiągnąć około 195-245 cm. W zimie ptaki tego gatunku konsumują przeciętnie 0,8 kg/dzień, zimą nawet do 3,1 kg/dzień, z czego połowę oddaje swoim pisklętom.", "category": "Sowy i Ptaki Drapieżne", "icon": "Pdr" }, "geometry": { "type": "Point", "coordinates": [ 17.003028380236472, 52.4017892834501 ] } },
{ "type": "Feature", "properties": { "fid": 81, "name": "Pustułka zwyczajna", "comments": "Polska nazwa pochodzi od rosyjskiego słowa 'pustoj' ('głupi'). Pustułki polują inaczej niż pozostałe ptaki drapieżne; w związku z tym, sokolnicy mieli problem z ich szkoleniem. Doskonały wzrok pomaga dostrzec zdobycz z wysokości nawet 20 -30 m. Pustułka w trakcie polowania potrafi zawisnąć w powietrzu. Po wypatrzeniu ofiary pikuje i zwalnia tuż nad ziemią. Widzi promieniowanie UV, jak wiele innych gatunków ptaków. Wykorzystuje to w specyficzny sposób - lokalizuje ślady moczu gryzoni, pozostawione blisko gniazd i nor.", "category": "Sowy i Ptaki Drapieżne", "icon": "PSow" }, "geometry": { "type": "Point", "coordinates": [ 17.002461263716111, 52.401963816871891 ] } },
{ "type": "Feature", "properties": { "fid": 82, "name": "Milu chiński ", "comments": "Byki zrzucają poroże jak większość jeleni. Drugie, małe poroże wyrasta czasem po raz drugi. Samiec pozbywa się go po kilku tygodniach. Pomimo swojej rosłej postury, są bardzo dobrymi pływakami lubią spędzać większość czasu zanurzone w zbiornikach wodnych. Ich średnią długość życia w warunkach Ogrodu Zoologicznego szacuje się na 23-25 lat. <br> <img src='./Animal_photos/82.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Małe ssaki i naczelne", "icon": "JnMc" }, "geometry": { "type": "Point", "coordinates": [ 17.001112334361565, 52.402529414045837 ] } },
{ "type": "Feature", "properties": { "fid": 83, "name": "Ryś", "comments": "Dzień spędza w kryjówce, dopiero o zmierzchu wychodzi na łowy. Po upolowaniu zdobyczy, resztki ukrywa na następne dni. Zakopuje je w ściółce tylnymi łapami, zakrywa liśćmi, piaskiem lub śniegiem. Pędzelki na końcach uszu skupiają fale dźwiękowe i doprowadzają je do uszu. Dzięki temu ryś lepiej słyszy. Ma doskonały wzrok. Jest w stanie zauważyć mysz z odległości 70 metrów, a pasącą się sarnę z ponad 0,5 km. Sprawnie wspina się po drzewach, dobrze skacze lecz nie jest wytrwałym biegaczem (szybko się męczy).", "category": "Rysie", "icon": "Rys" }, "geometry": { "type": "Point", "coordinates": [ 17.000187538737734, 52.401977794383562 ] } },
{ "type": "Feature", "properties": { "fid": 84, "name": "Nosorożec biały", "comments": "Nosorożce białe są trawożercami - ich szeroki pysk jest idealnie przystosowany do takiej diety. Są też największymi ze wszytkich nosorożców. Masa ciała samców może sięgać nawet 2500 kg. Ciąża u nosorożca białego trwa 17 - 18 miesięcy, rodzi się zawsze jedno młode, którego masa ciała waha się między 45 a 55 kg. Ogród Zoologiczny w Poznaniu jest jedynym w Polsce, w którym mieszkają dwa gatunki nosorożców.", "category": "Nosorożce", "icon": "Ns" }, "geometry": { "type": "Point", "coordinates": [ 16.999407889014993, 52.40276822796821 ] } },
{ "type": "Feature", "properties": { "fid": 85, "name": "Wydra europejska", "comments": "Aktywne głównie nocą, nawet wtedy potrafi polować na ryby pod grubą warstwą lodu. Na brzegu buduje nory, wejście do nich znajduje się pod powierzchnią wody. Oprócz otworu wejściowego, nory posiadają otwory wentylacyjne, znajdujące się pod korzeniami drzew. Prędkości zwierzęciu dodają błony pławne między palcami, które umożliwiają wydrze 'odpychanie' się od wody. W Polsce występuje na terenie całego kraju, najczęściej na Pomorzu, Warmii i Mazurach, Podkarpaciu, w Białostockiem i Łomżyńskiem.", "category": "Małe ssaki i naczelne", "icon": "Mlssk" }, "geometry": { "type": "Point", "coordinates": [ 16.998469315206918, 52.402539507824976 ] } },
{ "type": "Feature", "properties": { "fid": 86, "name": "Nilgau indyjski", "comments": "Hindusi niechętnie na nią polują ze względu na podobieństwo do świętych krów indyjskich (zebu). Antylopy te są aktywne głównie w dzień. Żyją około 1,5 lat. Ich głównymi wrogami są lamparty i tygrysy. Nilgau żyją w stadach od 4 do 20 osobników. Stare samce przechodzą czasem do samotniczego trybu życia. <br> <img src='./Animal_photos/86.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Wol" }, "geometry": { "type": "Point", "coordinates": [ 16.998820268811283, 52.402094069058002 ] } },
{ "type": "Feature", "properties": { "fid": 87, "name": "Antylopa szabloroga", "comments": "W polskim nazewnictwie antylopę tą nazywa się również antylopowcem szablorogim co podkreślić ma dalsze pokrewieństwo z pozostałymi antylopami. Samce pilnie strzegą swoich terytoriów, regularnie patrolując jego granice. Potężne rogi służą antylopom do obrony przed lwami, lampartami i hienami. Odnotowano przypadki, gdy broniąca się antylopa śmiertelnie raniła napastnika. Z wiekiem ich umaszczenie staje się coraz ciemniejsze. Samice stają się ciemnobrązowe, a samce czarne. <br> <img src='./Animal_photos/87.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Duże ssaki roślinożerne", "icon": "Ant" }, "geometry": { "type": "Point", "coordinates": [ 16.997966613153217, 52.401816035603289 ] } },
{ "type": "Feature", "properties": { "fid": 88, "name": "Sitatunga sawannowa", "comments": "U tych antylop występuje wyraźny dymorfizm, czyli różnice w wyglądzie płci. Dorosłe samce są duże, posiadają rogi i ciemnobrązowe umaszczenie. Bezrogie samice osiągają mniejsze rozmiary, a ich sierść jest czerwonopłowa. Często chowają się w wodzie przed drapieżnikami. Długie racice w kształcie banana pomagają cicho i sprawnie poruszać się po bagnistych terenach. Sitatungi stają na tylnych nogach, by dosięgnąć do rosnących wysoko liści. Samce używają też swoich rogów, do łamania gałęzi pełnych pożywienia. Do komunikacji używają wielu dźwięków o różnym znaczeniu. Ostrzegawcze szczekanie samic jest słyszalne na duże odległości.", "category": "Duże ssaki roślinożerne", "icon": "Wol" }, "geometry": { "type": "Point", "coordinates": [ 16.996782507801456, 52.401710597239742 ] } },
{ "type": "Feature", "properties": { "fid": 89, "name": "Dzioborożec białodzioby", "comments": "Częściej chodzi po ziemi niż lata. W przeciwieństwie do innych dzioborożców gniazd nie zakłada w dziuplach.", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.995940986550899, 52.401263264287103 ] } },
{ "type": "Feature", "properties": { "fid": 90, "name": "Sambar sundajski", "comments": "Mimo introdukcji na nowe terytoria, liczebność populacji na rodzimych terenach stale spada. Obecnie gatunek ma status 'narażony na wyginięcie' i jest chroniony na mocy indonezyjskiego prawa. W odróżnieniu od większości innych jeleniowatych, sierść młodych nie jest pokryta cętkami. W warunkach naturalnych praktycznie nie piją wody, wykorzystują płyny zawarte w zjadanych trawach i liściach. Poroże samców jest silnie rozgałęzione, może ono ważyć nawet ok. 2,5 kg. To bardzo dużo, w stosunku do masy ciała.", "category": "Duże ssaki roślinożerne", "icon": "JnS" }, "geometry": { "type": "Point", "coordinates": [ 16.995669174399424, 52.400726043956354 ] } },
{ "type": "Feature", "properties": { "fid": 91, "name": "Kanura patagońska", "comments": "Nazywana jest również patagonką. Żyje stadnie, w pobliżu cieków wodnych, na wysokości do 2000 m n.p.m. Gniazduje w tunelach, wykopanych w skałach wapiennych. Pojedyncze korytarze osiągają do 3 m głęgokości i łączą się z innymi w rozległe labirynty. Dymorfizm płciowy jest słabo widoczny gołym okiem. Ubarwienie znacznie w świetle UV. Kanura patagońska jest w stanie zwiększyć swoją masę ciała i spowolnić przemianę materii. W ten sposób oszczędza energię i może przetrwać mroźne zimy, przy mniejszej dostępności poakrmu.", "category": "Ptaki ozdobne i wodne", "icon": "Ppg" }, "geometry": { "type": "Point", "coordinates": [ 16.995999197547143, 52.400461550619561 ] } },
{ "type": "Feature", "properties": { "fid": 92, "name": "Pekińczyk czerwonodzioby", "comments": "Jest powszechny w hodowli, ze względu na kolorowe ubarwienie i melodyjny śpiew. Pomimo atutów, jest gatunkiem skrytym i trudnym w obserwacji. Lata rzadko, za wyjątkiem przemieszczania się w otwartych, niezalesionych przestrzeniach. Potrafi doskonale naśladować odgłosy innych gatunków ptaków. W sezonie lęgowym śpiew słowika chińskiego jest bardziej melodyjny; poza sezonem - jest mniej złożony, służy głównie komunikacji. Został sprowadzony do Europy jako ptak ozdobny. Osobniki, które uciekły z hodowli zadomowiły się w wielu krajach, gdzie utworzyły dzikie populacje. W naturalnym środowisku liczebność tego gatunku spada poprzez utratę siedlisk, Miejscowo jest objęty ochroną, w innych krajach jest uznawany za inwazyjny gatunek obcy (IGO).", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.996059693423369, 52.400446857915291 ] } },
{ "type": "Feature", "properties": { "fid": 93, "name": "Kariama czerwononoga", "comments": "W językach obcych z grupy Tupi słowo 'kariama' lub 'seriema' oznacza 'czubaty'. Wydaje skowyczące odłosy. Charakterystyczny, donośny głos tych ptaków przypomina gulgot lub histeryczny śmiech. Jest doskonałym biegaczem, lata rzadko woli chodzić. Przed niebezpieczeństwem ucieka opuszczając głowę. Samica składa dwa jaja, które wysiadują obydwoje rodzice. Pisklęta po wykluciu pokryte są puchem i pozostają przez pewien czas w gnieździe. <br> <img src='./Animal_photos/93.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.994935321600163, 52.400760019299994 ] } },
{ "type": "Feature", "properties": { "fid": 94, "name": "Czubacz rudy", "comments": "Pomimo, iż zręcznie porusza się w koronach drzew, wiele czasu spędza na ziemi. Samiec ma na głowie kędzierzawy czubek oraz żółtą narośl na dziobie. Podczas toków samiec wydaje głębokie buczenie, chcąc zwrócić na siebie uwagę samicy. Połyka małe kamienie, które są wykorzystywane do mielenia pokarmu w żołądku. Dziękitemu jest w stanie strawić nawet niedojrzałe owoce, które są jeszcze zielone i twarde.", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.994943789974869, 52.40080582989561 ] } },
{ "type": "Feature", "properties": { "fid": 95, "name": "Olśniak himalajski", "comments": "Zwany również 'monal', jest symbolem Nepalu. Nazwa łacińska upamiętniała Lady Mary Impey - żonę prezesa brytyjskiego sądu najwyższego Bengalu, sir Elijaha Impeya. U tego gatunku występuje wyraźny dymorfizm płciowy, czyli różnice w wyglądzie samca i samicy. Pióra kogutów są wielokolorowe, z metalicznym połyskiem; kury mają ubarwienie szaro-brązowe. Żyje na wysokości od 2400 do 4500 m n.p.m. Dobrze znosi niekorzystne warunki atmosferyczne i potrafi przekopywać się przez śnieg w poszukiwaniu pożywienia. Choć obecnie nie jest zagrożony wyginięciem, liczebność osobników na wolności wciąż spada. <br> <img src='./Animal_photos/95.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.994973467858401, 52.400957870680202 ] } },
{ "type": "Feature", "properties": { "fid": 96, "name": "Kitta czerwonodzioba", "comments": "Długość ciała wraz z ogonem wynosi do 70 cm. Wydaje dźwięki przypomianające przechotanie i gwizdanie. Bardzo dobrze naśladuje inne ptaki i różne dźwięki z otoczenia. Gdy żeruje zadziera do góry ogon, którego końcówka opada do dołu. Długie i eleganckie ogony tych ptaków zwracjaą uwagę z daleka, szczególnie podczas przeltoów stada. <br> <img src='./Animal_photos/96.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Kitt" }, "geometry": { "type": "Point", "coordinates": [ 16.995011676128033, 52.401025303363575 ] } },
{ "type": "Feature", "properties": { "fid": 97, "name": "Kiściec annamski", "comments": "Od 2000 roku nie udokumentowano żadnego osobnika w naturalnym środowisku. Podejrzewa się, że dziko żyjący przedstawiciele tego gatunku wymarli lub zostało ich nie więcej niż 250. Jest krytycznie zagrożonym endemitem Wietnamu - na wolności nie występuje nigdzie indziej na świecie. Krytuczny spadek liczebności populacji spowodowały m.in.: polowania, odłowy, opryski herbicydami podczas wojny w Wietnami oraz wyręby lasów na potrzeby rolnictwa. U tego gatunku występuje dymorfizm - widoczne różnice w wyglądzie płci. Samice są brązowe, a samce granatowe, z metalicznym połyskiem i białym czubem. <br> <img src='./Animal_photos/97.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.995029473915224, 52.401048232167668 ] } },
{ "type": "Feature", "properties": { "fid": 98, "name": "Sójka iberyjska", "comments": "Sójka iberyjska i jej azjatycka kuzynka - sójka błękitna, przez wiele lat były uważane za jeden gatunek. Wierzono, że populacja europejska, została sprowadzona z Azji. Archeolodzy odnaleźli jednak na Półwyspie Iberyjskim szczątki tego gatunku, sprzed 44 tys. lat. Dawniej nazywana 'sroką błękitną', tak jak inne sójki i sroki należy do krukowatych. Wszystkie ptaki z tej rodziny, wyróżnia zdolność do planowania złożonych działań i szybkiego uczenia się. Mogą tworzyć duże stada liczące nawet około 70 osobników. Sójki iberyjskie wsólnie szukają pożywienia i gniazdują blisko siebie. Na jedno drzewo, przypada jednak tylko jedno gniazdo. <br> <img src='./Animal_photos/98.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.99505692372561, 52.401095734923956 ] } },
{ "type": "Feature", "properties": { "fid": 99, "name": "Tragopan satyr", "comments": "Występuje u nich wyraźny dymorfizm płciowy. Samce są bardziej kolorowe niż samice. W czasie tańca godowego nadymają błękitne narośle na głowie przypominające rogi mitycznych satyrów. W odróżnieniu od innych bażantów i kuraków spędzających większą część życia na ziemi, tragopany spędzają sporo czasu na drzewach i tam budują gniazda. Często wykorzystują opuszczone gniazda większych ptaków. <br> <img src='./Animal_photos/99.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.995106459605307, 52.401294601558831 ] } },
{ "type": "Feature", "properties": { "fid": 100, "name": "Kiściec srebrzysty", "comments": "Żyje w niewielkich grupach, składających się zazwyczaj z jednego samca i kilku samic. Jest aktywny w ciągu dnia, a żeruje rano i wieczorem. Choć posiada zdolność lotu, przemieszcza się chodząc lub biegając. Skrzydeł używa główmie do ucieczki przed zbliżającym się zagrożeniem. Gniazda buduje na ziemi. Samice oraz pisklęta chronią się przed drapieżnikami dzięki kamuflującemu brązowo-szaremu upierzeniu. Podczas zalotów, czerwień na głowie samca tego bażanta uwydatnia się i jaśniej. Poza okresem godowym, pozostaje ciemniejsza i matowa. <br> <img src='./Animal_photos/100.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.995184606127982, 52.401381218912732 ] } },
{ "type": "Feature", "properties": { "fid": 101, "name": "Bażant złocisty", "comments": "Ptak ten żyje zwykle pojedynczo. W okresie godów samiec gromadzi wokół siebie kilka samic. Samica składa 8-12 jaj. Okres inkubacji trwa 3 tygodnie. Lata rzadko i na krótkich dystansach. Podobnie jak inne bażanty preferuje poruszanie się pieszo. W Chinach od bardzo dawna był hodowany jako ptak ozdobny.", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.995204660887914, 52.401418369084666 ] } },
{ "type": "Feature", "properties": { "fid": 102, "name": "Paw indyjski ", "comments": "Gatunek ten wykazuje dymorfizm, czyli wyraźne różnice w wyglądzie płci. Samce wyróżnia wielobarwne upierzenie, kolorowy czub na głowie i wielki okazały tren. Samice są mniejsze, o upierzeniu brązowo-białym z domieszką zieleni na głowie i czubie. Pawie bardzo dobrze latają, jednak większość czasu przebywają na ziemi, żerując. Noce spędzają w grupach, śpiąc wysoko na gałęziach drzew, słupach lub dachach. W wielu kulturach i wierzeniach uważane są za zwierzęta święte. Niektóre bóstwa przedstawiane są w postaci pawia lub z pawim piórem, jako świętym atrybutem. <br> <img src='./Animal_photos/102.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Paw" }, "geometry": { "type": "Point", "coordinates": [ 16.995225110443091, 52.401467341891696 ] } },
{ "type": "Feature", "properties": { "fid": 103, "name": "Uszak siwy", "comments": "Uszaki mają bardzo silne i ciężkie dzioby, których używają do grzebania w ziemi. Często można je obserować w górach na granicy wiecznego śniegu. Głosy samców mogą być słyszane nawet z odległości 1,5 km. Na głos samca odpowiadając zarówno potencjalne partnerki, jak i rywalizują z nim inne samce.", "category": "Ptaki ozdobne i wodne", "icon": "Pt" }, "geometry": { "type": "Point", "coordinates": [ 16.995221710849044, 52.401522046911438 ] } },
{ "type": "Feature", "properties": { "fid": 104, "name": "Myszołów zwyczajny", "comments": "Myszołowy mieszkające w naszej wolierze trafiły do nas po wypadkach. Udało się uratować im życie, jednak ze względu na poniesione obrażenia nie mogą wrócić na wolność. Są to najliczniej występujące ptaki drapieżne w Polsce. Gniazda zakładają w rozwidleniu gałęzi, wysoko na drzewie. Jedna para może korzystać z tego samego gniazda przez kilka lat. Młodych w lęgu najczęściej 3-4. <br> <img src='./Animal_photos/104.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Sowy i Ptaki Drapieżne", "icon": "Pdr" }, "geometry": { "type": "Point", "coordinates": [ 16.995289808430435, 52.401667602349811 ] } },
{ "type": "Feature", "properties": { "fid": 105, "name": "Świnia wisajska", "comments": "Jest to gatunek krytycznie zagrożony wyginięciem. Liczebność śiń wisajskich na wolności wynosi jedynie ok. 200 osobnikiów. Główne zagrożenia stanowią; wycinka lasów, kłusownictwo oraz krzyżowanie się ze świnią domową. Jest jedynym gatunkiem świniowatych, u którego stwierdzono wykorzystanie nardzędzia (płaski kawałek kory do kopania). 'Czupryna' widoczna od czubka głowy do końca grzbietuwystępuje wyłącznie u samców w okresie godowym. U prosiąt grzbiet pokrywają się kropki i paski, które zanikają z wiekiem. Jest jedynym z mniejszych gatunków świń. Samce osiągają do 30 kg, zaś samice do 20 kg.", "category": "Duże ssaki roślinożerne", "icon": "Swn" }, "geometry": { "type": "Point", "coordinates": [ 16.995139327876124, 52.402326072003909 ] } },
{ "type": "Feature", "properties": { "fid": 106, "name": "Kangur olbrzymi", "comments": "Potężny ogon pełni rolę podporową, pomaga utrzymywać równowagę. Kangury olbrzymie mogą wykonywać skoko i na odległość do 9 metrów i skacząc osiągać prędkość ponad 50 km/h. Samice rodzą młode po bardzo krótkiej około miesięcznej ciąży. Noworodek ma wielkość około 3 cm. Żyją w niewielkich grupach składających się z dominującego samce, 2 samic i 2 - 3 młodych samców.", "category": "Duże ssaki roślinożerne", "icon": "Kan" }, "geometry": { "type": "Point", "coordinates": [ 16.995350789547647, 52.401991299534373 ] } },
{ "type": "Feature", "properties": { "fid": 107, "name": "Sambar kropkowany", "comments": "Jeden z najrzadszych ssaków na świecie. Gatunek ten jest niezwykle trudny do obserwacji i badania, ze względu na rozbite populacje, których liczebność stale maleje. Ze względu na swój rozmiar, prowadzi głównie nocny tryb życia i trzyma się silnie zalesionych terenów lub gęsto porośniętych łąk. Dzięki temu może łatwo schronić się przed większymi drapieżnikami. Przez wiele lat obawiano się, że mógł wyginąć na wolności. W 2009 roku, badacze odnaleźli jednak odchody i tropy tego gatunku, głęboko w lasach Parku Narodowego North Negos.", "category": "Duże ssaki roślinożerne", "icon": "JnS" }, "geometry": { "type": "Point", "coordinates": [ 16.995572963884058, 52.402352940762057 ] } },
{ "type": "Feature", "properties": { "fid": 108, "name": "Emu zwyczajne", "comments": "Wysiadywaniem jaj oraz odchowaniem piskląt zajmuje się wyłącznie samiec. Emu nie potrafi latać, jednak bardzo dobrze pływa i łatwo przystosowuje się do różnych środowisk. Jest drugim po strusiu największym żyjącym ptakiem. Osiąga do 2 m wysokości i masę ciała do 55 kg. Samica jest cięższa od samca o około 5 kg. <br> <img src='./Animal_photos/108.jpg' alt='Zdjęcie wybiegu' style='width: 100%; border-radius: 5px; margin-top: 30px;'>", "category": "Ptaki ozdobne i wodne", "icon": "Emu" }, "geometry": { "type": "Point", "coordinates": [ 16.995878571719267, 52.4019735165868 ] } },
{ "type": "Feature", "properties": { "fid": 109, "name": "Akrobatka karliczka", "comments": "Ogon akrobatki karliczki przypomina pióro, ze względu na dwa rzędy włosów znajdujące się po bokach. Jest on wykorzystywany do lotu ślizgowego, tak samo jak błona lotna, rozciągnięta między kończnami. Struktura opuszków palców pozwala wspinać się i przemieszczać po całkiem płaskich powierzchniach nawet po szkle. Mimo podobieństwa do gryzoni akrobatka karlicza jest torbaczem, tak samo jak kangury, koale czy oposy.", "category": "Pawilon zwierząt nocnych", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 16.995129473268712, 52.399609722837511 ] } },
{ "type": "Feature", "properties": { "fid": 110, "name": "Podskoczek egipski", "comments": "Ten gryzoń spędza dni w norach i aktywny jest głównie w nocy, dzięki czemu chroni się przed upałem i odwodnieniem. Wodę pobiera głównie z pokarmu roślinnego, do którego musi mieć dostęp na swoim terytorium. W trakcie najgorętszych miesięcy zapada w estywację (sen letni) - odpowiednik snu zimowego. Porusza się wykonując długie, nawet kilkumetrowe skoki. Potrafi podpierać się ogonem dla zachowania równowagi.", "category": "Pawilon zwierząt nocnych", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 16.995115984378284, 52.399574371922597 ] } },
{ "type": "Feature", "properties": { "fid": 111, "name": "Kowari", "comments": "Naziemny torbacz zamieszkujący pustynne i suche stepy. Dzień spędza w norach i szczelinach skalnych. Odżywia się owadami, gadami i drobnymi ssakami.", "category": "Pawilon zwierząt nocnych", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 16.995096267541655, 52.399530917442988 ] } },
{ "type": "Feature", "properties": { "fid": 112, "name": "Galago senegalski", "comments": "Tak jak człowiek, małpy i lemury, należy do rzędu naczelnych. Prowadzi nadrzewny tryb życia - po gałęziach porusza się z niezwykłą szybkością, biegając i skacząc. W utrzymaniu równowagi pomaga mu długi ogon. Buduje gniazda z liści. Kilka dni po porodzie, samica przenosi swoje młode w pysku i układa je na gałęziach, na czas poszukiwania pokarmu. Choć nie widzi w całkowitej ciemności, duże, ciemne oczy umożliwiają widzenie przy bardzo ograniczonym, nocnym świetle.", "category": "Pawilon zwierząt nocnych", "icon": "Gls" }, "geometry": { "type": "Point", "coordinates": [ 16.995055922460704, 52.399365022684421 ] } },
{ "type": "Feature", "properties": { "fid": 113, "name": "Włosopuklerznik kosmaty ", "comments": "Ma silne, zakończone ostrymi pazurami łapy. Służą one do zdobywania pożywienia,ochrony przed drapieżnikami i kopania nor. Pod ziemią oddycha korzystając z niewielkiej ilości tlenu, zgromadzonego między cząstkami gleby. Twardy pancerz doskonale chroni przed drapieżnikami. Składa się z ok. 18 rzędów płytek kostnych. Część z nich jest ruchoma i umożliwia zwinięcie się.", "category": "Pawilon zwierząt nocnych", "icon": "Pcn" }, "geometry": { "type": "Point", "coordinates": [ 16.99509364200221, 52.399359942451433 ] } },
{ "type": "Feature", "properties": { "fid": 114, "name": "Nietoperz wampir", "comments": "Odżywia się krwią ssaków. W ślinie posiada substancję zapobiegającą krzepnięciu krwi. W ciągu dnia śpi w koloniach liczących nawet 2 tys. osobników. Po około 7-miesięcznej ciąży rodzi się jedno młode. Żyje do 20 lat.", "category": "Pawilon zwierząt nocnych", "icon": "Niet" }, "geometry": { "type": "Point", "coordinates": [ 16.995153077165959, 52.399377966100943 ] } },
{ "type": "Feature", "properties": { "fid": 116, "name": "Liścionis mniejszy", "comments": "Przedstawiciel rodziny liścionosów, obejmującej 50 rodzajów ze 129 gatunkami. Odżywia się owadami, owocami i nektarem. Dni spędza w jaskiniach i opuszczonych dziuplach drzew. Liścionosy nie zapadają w sen zimowy. Podobnie jak wiele innych gatunków z tej rodziny, nietoperz ten posiada zdolność echolokacji. Żyje w dużych grupach. Rodzi jedno młode.", "category": "Pawilon zwierząt nocnych", "icon": "Niet" }, "geometry": { "type": "Point", "coordinates": [ 16.995195832919201, 52.399487844794059 ] } },
{ "type": "Feature", "properties": { "fid": 117, "name": "Kanguroszczurnik pędzloogonowy ", "comments": "Jest torbaczem, prowadzi nocny tryb życia. Wyróżnia go charakterystyczna dieta, oparta głównie na wykopanych grzybach, żywicy, nasionach i bulwach. Nie je zielonych części roślin i potrafi żyć bez dostępu do wody. Zapasy tłuszczu gromadzi w ogonie. Gniazdo buduje sam, wyścieła wnętrze trawą i liśćmi. Materiały do budowy przenosi, przyciskając je przednimi łapami do brzucha. Tak przygotowane schronienie stanowi miejsce odpoczynku, nie odchowu młodych.", "category": "Pawilon zwierząt nocnych", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 16.995206761875256, 52.399515931248857 ] } },
{ "type": "Feature", "properties": { "fid": 118, "name": "Kitanka lisia", "comments": "Roślinożerny ssak. Prowadzi nocny, częściowo nadrzewny tryb życia. Jest torbaczem, młode spędzają pierwsze 5 miesięcy w torbie, na brzuchu matki, gdzie piją mleko i intensywnie rosną. Żywi się głównie roślinami i okazjonalnie owadami. Ma chwytny ogon , neowłosiony od spodniej strony - taka budowa zwiększa przyczepność i pomaga we wspinaczce. Jest samotnikiem, dystans od innych osobników zachowuje dzięki sygnałom zapachowym. Śpi w dzuplach i zagłębieniach skalnych. Konkuruje z innymi kitankami o miejsca do legowisk.", "category": "Pawilon zwierząt nocnych", "icon": "Kit" }, "geometry": { "type": "Point", "coordinates": [ 16.995216560428105, 52.399541112651761 ] } },
{ "type": "Feature", "properties": { "fid": 119, "name": "Kinkażu", "comments": "Nadrzewny drapieżnik spokrewniony z szopem praczem. Posiada chwytny ogon. Odżywia się zarówno pokarmem roślinnym jai i zwierzęcym. Rodzi do 4 młodych.", "category": "Pawilon zwierząt nocnych", "icon": "Gls" }, "geometry": { "type": "Point", "coordinates": [ 16.995228481869088, 52.399571749667558 ] } },
{ "type": "Feature", "properties": { "fid": 120, "name": "Rudawka nilowa", "comments": "Jest jedynym przedstawicielem rodziny rudawkowatych posługujący się echolokacją. Nie wydaje dźwięku za pomocą krtani, lecz mlaszcząc językiem. Po zapadnięciu zmroku wylatuje w poszukiwaniu owoców i nektaru kwiatów, pokonując nawet kilkadziesiąt kilometrów. Żyje do 20 lat.", "category": "Pawilon zwierząt nocnych", "icon": "Niet" }, "geometry": { "type": "Point", "coordinates": [ 16.995241179247877, 52.399604380749352 ] } },
{ "type": "Feature", "properties": { "fid": 121, "name": "Pancernik bolita", "comments": "Szczerbak z rodziny pancerników. Preferuje suche formacje roślinne. Nie kopie nor. W przypadku zagrożenia zwija się w regularną kulę. Kończymny przednie czteropalczaste, w tylnych zrośnięte pazury trzech palców przypominają kopytko. Biega na palcach. Żywi się mrówkami, termitami i owocami. Po 120-dniowej ciąży, samica rodzi jedno młode, otwierające oczy po 22-dniach. Nasze pancerniki otrzymyaliśmy z Paragwaju.", "category": "Pawilon zwierząt nocnych", "icon": "Pcn" }, "geometry": { "type": "Point", "coordinates": [ 16.995235279905106, 52.399589219990474 ] } },
{ "type": "Feature", "properties": { "fid": 122, "name": "Konczyl mniejszy", "comments": "Najmniejszy ssak kopytny świata o wadze 2-2,5 kg. Zamieszkuje lasy tropikalne o gęstym poszyciu. Żywi się opadłymi z drzew owocami, pączkami, młodymi gałązkami i grzybami. Samce mają wydłużone kły i znakują terytorium gruczołami znajdującymi się pod brodą. Żyje pojedynczo lub w parach. Samica po około pięciomiesięcznej ciąży wydaje na śiat jedno młode, które jest miniaturką dorosłych i po pół roku osiąga dojrzałość. Żyje do 12 lat. <br><br> Kanczyl mniejszy zdobył w Polsce ogromną popularność dzięki internetowej piosence o nazwie „myszojeleń”.", "category": "Pawilon zwierząt nocnych", "icon": "MsJl" }, "geometry": { "type": "Point", "coordinates": [ 16.995252242808164, 52.399632813049998 ] } },
{ "type": "Feature", "properties": { "fid": 123, "name": "Kukang mały", "comments": "Zaniepokojony kukang często podnosi do góry przednie kończyny - to ostrzeżenie potencjalnego napastnika przed toksyczną substancją, wytwarzaną dzięki specjalnym gruczołom w okolicy łokci. Kukang ma doskonały słuch, a jego oczy są zaopatrzone w błonę odblaskową, która wspomaga widzenie w nocy. Pomimo międzynarodowej popularności nie nadaje się na zwierzę domowe. Kontakt z człowiekiem oraz wymuszanie dziennej aktywności, przyczynia się u tego gatunku do silnego stresu i cierpienia.", "category": "Pawilon zwierząt nocnych", "icon": "Gls" }, "geometry": { "type": "Point", "coordinates": [ 16.99526957493087, 52.399677354924663 ] } },
{ "type": "Feature", "properties": { "fid": 124, "name": "Jeżatka afrykańska ", "comments": "Jeden z największych gryzoni zamieszkujących Afrykę. Dni spędza w kryjówkach. Potrafi wspinać się na drzewa i doskonale pływa. Żyje w grupach rodzinnych. Pokarm jego stanowią głównie rośliny: liście, gałęzie, korzenie, owoce, bulwy. Podobnie jak u jeżozwierzy, część włosów jest przekształcona w kolce służące do obrony. Po trwającej 3,5 miesiąca ciąży samica wydaje na świat 1, rzadko 2 młode. Żyjące do 23 lat.", "category": "Pawilon zwierząt nocnych", "icon": "Jez" }, "geometry": { "type": "Point", "coordinates": [ 16.995223089295649, 52.399714564304794 ] } },
{ "type": "Feature", "properties": { "fid": 125, "name": "Żołędnica europejska", "comments": "W Polsce występuje tylko na terenach Babiogórskiego Parku Narodowego i podlega ścisłej ochronie. Wiedzie nadrzewny, nocny tryb życia. Buduje gniazda w dziuplach. Zapada w sen zimowy. Na zimę gromadzi zapasy, które zjada, kiedy się budzi.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001011428899744, 52.401486087328912 ] } },
{ "type": "Feature", "properties": { "fid": 126, "name": "Nornik wschodni", "comments": "Jest aktywny niezależnie od pory dnia. Na lądzie nie porusza się zbyt zwinnie i szybko, jest jednak doskonałym pływakiem. Wykopuje złożone, mocno rozbudowane nory, z bocznymi przejściami, komorami lęgowymi i wieloma wyjściami.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001098250715472, 52.401505528641195 ] } },
{ "type": "Feature", "properties": { "fid": 127, "name": "Myszoskocz okazały", "comments": "Prowadzi nocny tryb życia, choć jest aktywny również o zmierzchu i o świcie. Dzień spędza śpiąc, w wykopanej przez siebie w ziemi norze. Jest to też miejsce, gdzie chroni się przed drapieżnikami. Potrafi szybko i zwinnie skakać, co pomaga w ucieczce lub wspinaczce po skałach.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001093596350092, 52.401561995775189 ] } },
{ "type": "Feature", "properties": { "fid": 128, "name": "Kolcomysz arabska", "comments": "Jest aktywna w nocy; unika w ten sposób wysokiej temperatury w ciągu dnia. Żyje w małych grupach i jest bardzo społeczna. W wychowywaniu potomstwa pomaga matce inna samica. Jej kolczasta sierść pomaga uniknąć zjedzenia przez drapieżnika. W przypadku ataku, może też odrzucić swój ogon.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001094491420368, 52.40155085526321 ] } },
{ "type": "Feature", "properties": { "fid": 129, "name": "Mysz karłowata", "comments": "Układa kamienie przy wejściu do nory. Zebrana na nich rosa stanowi dla myszy karłowatej źródło pitnej wody. Żyje w pairs lub grupach, blisko zbiorników wodnych lub wysokiej trawie. Jest zwierzęciem nocnym - w ciągu dnia śpi w norze, a aktywność rozpoczyna po zmierzchu.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001097176631152, 52.401517324489475 ] } },
{ "type": "Feature", "properties": { "fid": 130, "name": "Myszak kaktusowy", "comments": "Najbardziej ruchliwy o zmierzchu. Aktywność spada podczas pełni księżuca. Jest bardzo szybki - podczas ucieczki potrafi biec z prędkością 13km/h, co przy jego rozmiarach jest dużym osiągniecniem. Przestraszony, wydaje przeraźliwy, wysoki pisk.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001096639588994, 52.4015272635814 ] } },
{ "type": "Feature", "properties": { "fid": 131, "name": "Podskoczek egipski", "comments": "Ten gryzoń aktywny jest głównie w nocy, dzięki czemu chroni się przed upałem i odwodnieniem. Dni spędza w podziemnych norach. W trakcie najgorętszych miesięcy zapada w estywację (sen letni) - odpowiednik snu zimowego. Porusza się wykonując długie, nawet kilkumetrowe skoki. Potrafi podpierać się ogonem dla zachowania równowagi.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001095565504681, 52.401539277865396 ] } },
{ "type": "Feature", "properties": { "fid": 132, "name": "Kururo niebieskawy", "comments": "Rzadko wychodzi na powierzchnię i żywi się wyłącznie pod ziemią. Zgromadzone cebulki i bulwy roślin przechowuje w swoich norach na zimę. Żyje w koloniach do ok. 15 osobników, złożonych z kilku par oraz ich młodych.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.001043830443351, 52.401574993035673 ] } },
{ "type": "Feature", "properties": { "fid": 133, "name": "Badylarka pospolita", "comments": "Używa chwytnego ogona, którym przytrzymuje się łodyg trawy, podczas zbierania pożywienia. Na łodygach traw buduje małe, kuliste gniazda o średnicy do 7 cm. Nie zapada w sen zimowy. Przenosi się w ciepłe miejsca z dostępem do suchych traw i zbóż.", "category": "Wszędobylskie gryzonie", "icon": "Ms" }, "geometry": { "type": "Point", "coordinates": [ 17.000975447075078, 52.401573900829057 ] } },
{ "type": "Feature", "properties": { "fid": 134, "name": "Skorpion", "comments": "Znamy około 600 gatunków skorpionów. Większość występuje na obszarach pustynnych i półpustynnych. Spłaszczone ciało skorpiona zakończone jest gruczołem jadowym. Tylko 24 gatunki mają jad groźny dla człowieka. Polują na owady, pająki i inne stawonogi. Prowadzą nocny tryb życia. Samica rodzi 20 - 30 młodych i nosi je na grzbiecie przez 3 tygodnie.", "category": "Owady", "icon": "OwSp" }, "geometry": { "type": "Point", "coordinates": [ 17.003945340933505, 52.401601395076028 ] } },
{ "type": "Feature", "properties": { "fid": 135, "name": "Ślimak olbrzymi ", "comments": "Największe lądowe ślimaki świata. Ciężar ciała może dochodzić do 0,5 kg, a wysokość muszli do 20 cm. Sąroślinożerne. Zamieszkują Afrykę Równikową, gdzie trzymają się miejsc wilgotnych. Rozpowrzechnione przez człowieka, stały się uciążliwym szkodnikiem upraw.", "category": "Owady", "icon": "OwSl" }, "geometry": { "type": "Point", "coordinates": [ 17.003830801551722, 52.401666685715583 ] } },
{ "type": "Feature", "properties": { "fid": 136, "name": "Modliszka", "comments": "Rząd owadów liczący ok. 2000 gatunków, żyjących głównie w rejonach klimatu subtropikalnego. Długość ich ciała wynosi od 10 mm - 16 cm. W Polsce żyje tylko modliszka pobożna. Upodabniają się do liści i gałązek, a z uwagi na budowę przednich odnóży przypominają modlącą się postać. Przechodzą przeobrażenie niezupełne. Podczas kopulacji samica częśto zjada samca.", "category": "Owady", "icon": "OwMd" }, "geometry": { "type": "Point", "coordinates": [ 17.003849384158006, 52.401655559501293 ] } },
{ "type": "Feature", "properties": { "fid": 137, "name": "Kolczak seszelski ", "comments": "Ten niezwykły chrząszcz o długości 3-4 cm zagrożony jest wyginięciem ze względu na mały obszar występowania, degradację środowiska oraz zawleczone przez człowieka szczury. Grupa zapaleńców z insektarium w Londynie rozpoczęła jego hodowlę. Uzyskano tam około 100 osobników, z czego 10 przesłano do naszego ZOO. Mamy nadzieję, że dzięki hodowli uda się uratować ten gatunek.", "category": "Owady", "icon": "Ow" }, "geometry": { "type": "Point", "coordinates": [ 17.003864681557207, 52.401647116061667 ] } },
{ "type": "Feature", "properties": { "fid": 138, "name": "Wije", "comments": "Gromada wijów obejmuje lądowe stawonogi o robakowatym ciele, pokrytym twardym pancerzem chitynowym. Ciało ich o długości od kilku milimatrów do kilkunastu centymetrów, składa się z głowy i licznych niezróżnicowanych segmentów zaopatrzonych w 1 lub 2 pary odnóży krocznych. Są aktywne nocą. Żyją pod korą, kamieniami i w ściółce. Część wijów jest drapieżna, część roślinożerna. W Polsce żyją: wij drewniak, zieminek i julus.", "category": "Owady", "icon": "OwWj" }, "geometry": { "type": "Point", "coordinates": [ 17.003879771072103, 52.401638450193467 ] } },
{ "type": "Feature", "properties": { "fid": 139, "name": "Pająk ptasznik ", "comments": "Pająk ten dysponuje jadem zdolnym zabić małe ptaki, gryzonie i jaszczórki. Indianie używali tego jadu do zatruwania strzał. Łamliwe włoski pokrywające jego ciało są bronią - powodują podrażnienia skóry. Ptaszniki żują w dziuplach drzew, w norach i czelinach skalnych. Nie budują sieci, lecz polują aktywnie.", "category": "Owady", "icon": "OwPj" }, "geometry": { "type": "Point", "coordinates": [ 17.003896240364995, 52.401629057229222 ] } },
{ "type": "Feature", "properties": { "fid": 140, "name": "Modliszka liściogłowa ", "comments": "Dorastają do około 5-6 cm. Samice są trochę większe od samców. Mogą mieć różne ubarwienie: od czarnej poprzez brąz i różne odcienie beżu aż do zieleni. Żyją na sawannie. Polują głównie na owady latające.", "category": "Owady", "icon": "OwMd" }, "geometry": { "type": "Point", "coordinates": [ 17.003926135017711, 52.40161274115524 ] } },
{ "type": "Feature", "properties": { "fid": 141, "name": "Szarańcza fioletowa", "comments": "Żyje w tropikalnych lasach deszczowych Gujany Francuskiej. Żywi się liśćmi bananowców i helikonii. Jaja składa na ziemi.", "category": "Owady", "icon": "Ow" }, "geometry": { "type": "Point", "coordinates": [ 17.003915839661239, 52.401579792897138 ] } },
{ "type": "Feature", "properties": { "fid": 142, "name": "Modliszka patyczkowata", "comments": "Żywi się muchami i latającymi owadami. Podobna jest do suchego patyka. Samica ma 16 cm długości, a samiec 13 cm. Głowa trójkątna z oczami wysuniętymi na boki. Zapłodniona samica przyczepia kokon jajowy do gałązki, Licznie wylęgające się młode prowadzą samodzielny drapieżny tryb życia.", "category": "Owady", "icon": "OwMd" }, "geometry": { "type": "Point", "coordinates": [ 17.00389752102604, 52.401590317995122 ] } },
{ "type": "Feature", "properties": { "fid": 143, "name": "Straszyk diabelski", "comments": "W naturze zamieszkuje zalewdie 5 ha w górskim rejonie Cordillera dal Condor, na wysokości 1200 - 1800 m n.p.m., na północy Peru. Gatunek ten jest wybitnie schlubny. Samice osiągają maks. do 8 cm, a samce 5 cm. Zaniepokojone wydzielają drażniącą substancję obronną.", "category": "Owady", "icon": "OwPt" }, "geometry": { "type": "Point", "coordinates": [ 17.003881600296538, 52.401598981288394 ] } },
{ "type": "Feature", "properties": { "fid": 144, "name": "Żuk afrykański", "comments": "Dyży, pięknie ubarwiony chrząszcz. Samica po kopulacji składa w podłożu białe, okrągłe jajeczka. Wylęgają się z nich pędrakowate larwy, które szybko rosną, żywiąc się próchnicą i owocami. Dorosła larwa buduje w ziemi twardy kokon, tzw, kokolit, w którym się przepoczwarza. Tam też poczwarka zmienia się w owada doskonałego, tzw. imago. Żuki żywią się płatkami róż i owoców.", "category": "Owady", "icon": "Ow" }, "geometry": { "type": "Point", "coordinates": [ 17.003861869666796, 52.401611691162145 ] } },
{ "type": "Feature", "properties": { "fid": 145, "name": "Patyczaki, Straszyki", "comments": "Te egzotyczne roślinożerne owady są klasycznym przykładem mimezji czyli upodabniania się wyglądem zewnętrznym do naturalnego otoczenia. Niektóre gatunki mają wygląd zielonych liści, suchych liści, kawałków kory czy gałązek. Inną reakcją obronną patyczaków jest zdolność do wpadania w stan odrętwienia zwany katalepsją lub akinezą.", "category": "Owady", "icon": "OwPt" }, "geometry": { "type": "Point", "coordinates": [ 17.003847024077018, 52.401621336735026 ] } },
{ "type": "Feature", "properties": { "fid": 146, "name": "Straszyk olbrzymi", "comments": "Największy roślinożerny owad o wyraźnym dymorfizmie płciowym. Bezskrzydłe, zielone samice osiągają 15 cm i masę ciała 17 g. Samce są mniejsze, inaczej ubarwione i mają dwie pary skrzydeł. Wylęgające się larwy mają 3 cm długości i żerują zbiorowo na liściach dębu, a w późniejszych stadiach na róży i jeżynia.", "category": "Owady", "icon": "OwPt" }, "geometry": { "type": "Point", "coordinates": [ 17.003832869390202, 52.401629384890796 ] } },
{ "type": "Feature", "properties": { "fid": 147, "name": "Karaczan madagaskarski", "comments": "Duży, roślinożerny karaczan bezskrzydły, dochodzący do 7 cm długości. Zaniepokojony ucieka głośno sycząc. Samce różnią się od samic niereguralnymi wypukłościami na przedpleczu. Są jajo-żyworodne. Samice noszą kokon jajowy w specjalnej komorze odwłoka, do czasu zakończenia rozwuju embrionalnego młodych. Potem larwy opuszcają go i rozpoczynają samodzielne życie.", "category": "Owady", "icon": "Ow" }, "geometry": { "type": "Point", "coordinates": [ 17.003819085308113, 52.401638122531963 ] } },
{ "type": "Feature", "properties": { "fid": 148, "name": "Karaczan olbrzymi", "comments": "Jeden z największych uskrzydlonych karaczanów. Długość jego ciała wynosi 7cm. Owad ten przechodzi niezupełne przeobrażenie. Larwy są spłaszczone grzbietowo-brzusznie. Żyją w warstwie humusu glebowego. Karaczan marmurkowy jest wszystkożerny. Zaniepokojony wydziela woń odstraszającą.", "category": "Owady", "icon": "Ow" }, "geometry": { "type": "Point", "coordinates": [ 17.003806573682006, 52.401646271936229 ] } }
]
};